import subprocess, os, json, time, signal, tempfile, pathlib
def run_batch(args, dur=2.2, env=None, cwd="/tmp/hwtest"):
    e=dict(os.environ); 
    if env: e.update(env)
    p=subprocess.Popen(["/workspace/executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=e)
    time.sleep(dur)
    p.send_signal(signal.SIGINT)
    try: out,err=p.communicate(timeout=2)
    except: p.kill(); out,err=p.communicate()
    return out.decode(errors='replace'), err.decode(errors='replace'), p.returncode

# logfile tests
import os
os.makedirs("/tmp/hwtest",exist_ok=True)
for f in ["/tmp/hwtest/log1.json"]:
    try: os.remove(f)
    except: pass
out,err,rc=run_batch(["-b","-n","0.5","-l","/tmp/hwtest/log1.json","echo hi"],dur=1.6)
print("log batch out",repr(out),"err",repr(err),"rc",rc)
print("logfile exists?", os.path.exists("/tmp/hwtest/log1.json"))
if os.path.exists("/tmp/hwtest/log1.json"):
    print(open("/tmp/hwtest/log1.json").read())

# changing command log
