def test(name, data):
    open("/tmp/hwtest/bad.json","w").write("xxx\n")
    p=subprocess.Popen(["/workspace/executable","-b","-n","0.5","-l","/tmp/hwtest/bad.json","echo hi"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE, cwd="/tmp/hwtest")
