    elif stdin_mode=="pipe": kwargs['stdin']=subprocess.PIPE
    else: kwargs['stdin']=subprocess.DEVNULL
    p=subprocess.Popen(["/workspace/executable","-n","100","echo hi"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, close_fds=True, **kwargs)
