{"command":"cat > src/exec.rs << 'RS'
use std::io::Read;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::sync::mpsc::{self, Receiver, Sender};
use std::thread;
use std::time::{Duration, Instant};

use crate::config::Settings;
use crate::result::CommandResultData;

#[derive(Clone)]
pub struct ExecControl {
    pub interval: f64,
    pub paused: bool,
    pub stopped: bool,
}

pub type SharedControl = Arc<Mutex<ExecControl>>;

pub fn new_control(interval: f64) -> SharedControl {
    Arc::new(Mutex::new(ExecControl { interval, paused: false, stopped: false }))
}

fn shell_split(s: &str) -> Vec<String> {
    match shlex::split(s) {
        Some(v) => v,
        None => panic!("shell command parse error.: ParseError"),
    }
}

pub fn execute_once(settings: &Settings, command: &str) -> CommandResultData {
    let mut result = CommandResultData {
        command: command.to_string(),
        ..Default::default()
    };

    let child_result = if settings.exec {
        let cmds = shell_split(command);
        // Indexing an empty command is intentional behaviour inherited from
        // the execution model: an empty exec target cannot be spawned.
        let program = cmds[0].clone();
        Command::new(&program)
            .args(&cmds[1..])
            .stdin(Stdio::inherit())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
    } else {
        let mut cmds = shell_split(&settings.shell_command);
        if cmds.iter().any(|c| c.contains("{COMMAND}")) {
            for c in cmds.iter_mut() {
                *c = c.replace("{COMMAND}", command);
            }
        } else {
            cmds.push(command.to_string());
        }
        let program = cmds[0].clone();
        Command::new(&program)
            .args(&cmds[1..])
            .stdin(Stdio::inherit())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
    };

    let mut child = match child_result {
        Ok(c) => c,
        Err(e) => {
            result.status = false;
            result.stderr = e.to_string();
            result.output = result.stderr.clone();
            result.timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S%.3f").to_string();
            return result;
        }
    };

    let mut out_pipe = child.stdout.take();
    let mut err_pipe = child.stderr.take();
    let (tx, rx): (Sender<(bool, String)>, Receiver<(bool, String)>) = mpsc::channel();
    let tx2 = tx.clone();
    let out_thread = thread::spawn(move || {
        let mut buf = Vec::new();
        if let Some(p) = out_pipe.as_mut() { let _ = p.read_to_end(&mut buf); }
        let _ = tx.send((true, String::from_utf8_lossy(&buf).into_owned()));
    });
    let err_thread = thread::spawn(move || {
        let mut buf = Vec::new();
        if let Some(p) = err_pipe.as_mut() { let _ = p.read_to_end(&mut buf); }
        let _ = tx2.send((false, String::from_utf8_lossy(&buf).into_owned()));
    });

    let status = child.wait();
    let mut stdout = String::new();
    let mut stderr = String::new();
    let mut output = String::new();
    for _ in 0..2 {
        match rx.recv() {
            Ok((is_out, text)) => {
                output.push_str(&text);
                if is_out { stdout = text; } else { stderr = text; }
            }
            Err(_) => break,
        }
    }
    let _ = out_thread.join();
    let _ = err_thread.join();

    result.status = status.map(|s| s.success()).unwrap_or(false);
    result.stdout = stdout;
    result.stderr = stderr;
    result.output = output;
    result.timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S%.3f").to_string();
    result
}

pub fn spawn_executor(settings: Settings, command: String, control: SharedControl) -> Receiver<CommandResultData> {
    let (tx, rx) = mpsc::channel::<CommandResultData>();
    thread::spawn(move || {
        let mut before_result = CommandResultData::default();
        loop {
            if control.lock().unwrap().stopped { break; }

            // Wait while paused; a paused executor does not start a command.
            loop {
                let (paused, stopped) = { let c = control.lock().unwrap(); (c.paused, c.stopped) };
                if stopped { return; }
                if !paused { break; }
                thread::sleep(Duration::from_millis(10));
            }

            let start = Instant::now();
            let result = execute_once(&settings, &command);
            let elapsed = start.elapsed();

            let changed = result != before_result;
            if changed {
                before_result = result.clone();
                if tx.send(result).is_err() { return; }
            }

            let (interval, stopped) = { let c = control.lock().unwrap(); (c.interval, c.stopped) };
            if stopped { return; }

            // Converting an invalid interval is expected to fail in this
            // worker thread (matching the reference behaviour).
            let mut wait = Duration::from_secs_f64(interval);
            if settings.precise {
                wait = wait.saturating_sub(elapsed);
            }
            // Sleep in small slices so pause/interval changes and shutdown
            // stay responsive. Entering pause restarts the wait, again in
            // line with the observed behaviour.
            let mut slept = Duration::ZERO;
            while slept < wait {
                let (paused, stopped, cur_interval) = { let c = control.lock().unwrap(); (c.paused, c.stopped, c.interval) };
                if stopped { return; }
                if paused {
                    // Wait for resume, then restart the interval wait.
                    loop {
                        let (p, s) = { let c = control.lock().unwrap(); (c.paused, c.stopped) };
                        if s { return; }
                        if !p { break; }
                        thread::sleep(Duration::from_millis(10));
                    }
                    let start2 = Instant::now();
                    let _ = start2;
                    // Recompute wait from the current interval, counting only
                    // a fresh wait after resume.
                    let ni = control.lock().unwrap().interval;
                    wait = Duration::from_secs_f64(ni);
                    slept = Duration::ZERO;
                    continue;
                }
                let _ = cur_interval;
                let slice = std::cmp::min(Duration::from_millis(10), wait - slept);
                thread::sleep(slice);
                slept += slice;
            }
        }
    });
    rx
}
RS
echo done"}

