        Err(e) => {
            result.status = false;
            result.stderr = e.to_string();
            result.output = result.stderr.clone();
            result.timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S%.3f").to_string();
            return result;
        }
    };

    let mut out_pipe = child.stdout.take();
    let mut err_pipe = child.stderr.take();
    let (tx, rx): (Sender<(bool, String)>, Receiver<(bool, String)>) = mpsc::channel();
    let tx2 = tx.clone();
    let out_thread = thread::spawn(move || {
        let mut buf = Vec::new();
        if let Some(p) = out_pipe.as_mut() { let _ = p.read_to_end(&mut buf); }
        let _ = tx.send((true, String::from_utf8_lossy(&buf).into_owned()));
    });
    let err_thread = thread::spawn(move || {
        let mut buf = Vec::new();
        if let Some(p) = err_pipe.as_mut() { let _ = p.read_to_end(&mut buf); }
        let _ = tx2.send((false, String::from_utf8_lossy(&buf).into_owned()));
    });

    let status = child.wait();
    let mut stdout = String::new();
    let mut stderr = String::new();
    let mut output = String::new();
    for _ in 0..2 {
        match rx.recv() {
            Ok((is_out, text)) => {
