pub fn spawn_executor(settings: Settings, command: String, control: SharedControl) -> Receiver<CommandResultData> {
    let (tx, rx) = mpsc::channel::<CommandResultData>();
    thread::spawn(move || {
        let mut before_result = CommandResultData::default();
        loop {
            if control.lock().unwrap().stopped { break; }

            // Wait while paused; a paused executor does not start a command.
            loop {
                let (paused, stopped) = { let c = control.lock().unwrap(); (c.paused, c.stopped) };
                if stopped { return; }
                if !paused { break; }
                thread::sleep(Duration::from_millis(10));
            }

            let start = Instant::now();
            let result = execute_once(&settings, &command);
            let elapsed = start.elapsed();

            let changed = result != before_result;
            if changed {
                before_result = result.clone();
                if tx.send(result).is_err() { return; }
            }

            let (interval, stopped) = { let c = control.lock().unwrap(); (c.interval, c.stopped) };
            if stopped { return; }

            // Converting an invalid interval is expected to fail in this
            // worker thread (matching the reference behaviour).
            let mut wait = Duration::from_secs_f64(interval);
            if settings.precise {
                wait = wait.saturating_sub(elapsed);
            }
            // Sleep in small slices so pause/interval changes and shutdown
            // stay responsive. Entering pause restarts the wait, again in
            // line with the observed behaviour.
            let mut slept = Duration::ZERO;
            while slept < wait {
                let (paused, stopped, cur_interval) = { let c = control.lock().unwrap(); (c.paused, c.stopped, c.interval) };
                if stopped { return; }
                if paused {
                    // Wait for resume, then restart the interval wait.
                    loop {
                        let (p, s) = { let c = control.lock().unwrap(); (c.paused, c.stopped) };
                        if s { return; }
                        if !p { break; }
                        thread::sleep(Duration::from_millis(10));
                    }
                    let start2 = Instant::now();
                    let _ = start2;
                    // Recompute wait from the current interval, counting only
                    // a fresh wait after resume.
                    let ni = control.lock().unwrap().interval;
                    wait = Duration::from_secs_f64(ni);
                    slept = Duration::ZERO;
                    continue;
                }
                let _ = cur_interval;
                let slice = std::cmp::min(Duration::from_millis(10), wait - slept);
                thread::sleep(slice);
                slept += slice;
            }
        }
    });
    rx
}
