#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum KeyCodeDef {
    Char(char),
    F(u8),
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    Backspace,
    Enter,
    Tab,
    BackTab,
    Esc,
    Delete,
    Insert,
    MouseScrollUp,
    MouseScrollDown,
    MouseScrollLeft,
    MouseScrollRight,
    MouseButtonLeft,
    MouseButtonRight,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct KeyDef {
    pub code: KeyCodeDef,
    pub ctrl: bool,
    pub alt: bool,
    pub shift: bool,
}

impl KeyDef {
    pub fn simple(code: KeyCodeDef) -> Self { Self { code, ctrl: false, alt: false, shift: false } }
    pub fn to_display(&self) -> String {
        if matches!(self.code, KeyCodeDef::MouseScrollUp) { return "mouse-scroll_up".to_string(); }
        if matches!(self.code, KeyCodeDef::MouseScrollDown) { return "mouse-scroll_down".to_string(); }
        if matches!(self.code, KeyCodeDef::MouseScrollLeft) { return "mouse-scroll_left".to_string(); }
        if matches!(self.code, KeyCodeDef::MouseScrollRight) { return "mouse-scroll_right".to_string(); }
        if matches!(self.code, KeyCodeDef::MouseButtonLeft) { return "mouse-button_down_left".to_string(); }
        if matches!(self.code, KeyCodeDef::MouseButtonRight) { return "mouse-button_down_right".to_string(); }
        let base = match self.code {
            KeyCodeDef::Char(' ') => "space".to_string(),
            KeyCodeDef::Char(c) => c.to_string(),
            KeyCodeDef::F(n) => format!("f{}", n),
            KeyCodeDef::Up => "up".to_string(),
            KeyCodeDef::Down => "down".to_string(),
            KeyCodeDef::Left => "left".to_string(),
            KeyCodeDef::Right => "right".to_string(),
            KeyCodeDef::Home => "home".to_string(),
            KeyCodeDef::End => "end".to_string(),
            KeyCodeDef::PageUp => "pageup".to_string(),
            KeyCodeDef::PageDown => "pagedown".to_string(),
            KeyCodeDef::Backspace => "backspace".to_string(),
            KeyCodeDef::Enter => "enter".to_string(),
            KeyCodeDef::Tab => "tab".to_string(),
            KeyCodeDef::BackTab => "backtab".to_string(),
            KeyCodeDef::Esc => "esc".to_string(),
            KeyCodeDef::Delete => "delete".to_string(),
            KeyCodeDef::Insert => "insert".to_string(),
            _ => unreachable!(),
        };
        let mut parts: Vec<String> = Vec::new();
        if self.ctrl { parts.push("ctrl".to_string()); }
        if self.shift { parts.push("shift".to_string()); }
        if self.alt { parts.push("alt".to_string()); }
        // The reference representation puts shift before alt for the
        // default shift-alt bindings; ctrl is shown first when present.
        // Reorder shift/alt if both present to match that convention.
        if self.shift && self.alt {
            parts = Vec::new();
            if self.ctrl { parts.push("ctrl".to_string()); }
            parts.push("shift".to_string());
            parts.push("alt".to_string());
        }
        parts.push(base);
        parts.join("-")
    }
}

pub fn parse_key(spec: &str) -> Option<KeyDef> {
    let s = spec.trim();
    if s.is_empty() { return None; }
    match s {
        "mouse-scroll_up" => return Some(KeyDef::simple(KeyCodeDef::MouseScrollUp)),
        "mouse-scroll_down" => return Some(KeyDef::simple(KeyCodeDef::MouseScrollDown)),
        "mouse-scroll_left" => return Some(KeyDef::simple(KeyCodeDef::MouseScrollLeft)),
        "mouse-scroll_right" => return Some(KeyDef::simple(KeyCodeDef::MouseScrollRight)),
        "mouse-button_down_left" => return Some(KeyDef::simple(KeyCodeDef::MouseButtonLeft)),
        "mouse-button_down_right" => return Some(KeyDef::simple(KeyCodeDef::MouseButtonRight)),
        _ => {}
    }
    let parts: Vec<&str> = s.split('-').collect();
    let (mods, base) = if parts.len() > 1 {
        (&parts[..parts.len() - 1], parts[parts.len() - 1])
    } else {
        (&[][..], parts[0])
    };
    // A lone '-' cannot be expressed in this syntax; callers use "minus".
    if base.is_empty() { return None; }
    let mut kd = KeyDef::simple(KeyCodeDef::Char('\0'));
    for m in mods {
        let ml = m.to_ascii_lowercase();
        if ml.contains("ctrl") || ml == "control" || ml == "ctl" { kd.ctrl = true; }
        if ml.contains("alt") { kd.alt = true; }
        if ml.contains("shift") { kd.shift = true; }
    }
    let bl = base.to_ascii_lowercase();
    kd.code = match bl.as_str() {
        "up" => KeyCodeDef::Up,
        "down" => KeyCodeDef::Down,
        "left" => KeyCodeDef::Left,
        "right" => KeyCodeDef::Right,
        "home" => KeyCodeDef::Home,
        "end" => KeyCodeDef::End,
        "pageup" => KeyCodeDef::PageUp,
        "pagedown" => KeyCodeDef::PageDown,
        "tab" => KeyCodeDef::Tab,
        "backtab" => { kd.shift = true; KeyCodeDef::BackTab }
        "backspace" => KeyCodeDef::Backspace,
        "enter" => KeyCodeDef::Enter,
        "esc" => KeyCodeDef::Esc,
        "space" => KeyCodeDef::Char(' '),
        "delete" | "del" => KeyCodeDef::Delete,
        "insert" => KeyCodeDef::Insert,
        "plus" => KeyCodeDef::Char('+'),
        "minus" | "hyphen" => KeyCodeDef::Char('-'),
        "equal" => KeyCodeDef::Char('='),
        _ => {
            if bl.starts_with('f') {
                if let Ok(n) = bl[1..].parse::<u8>() {
                    if (1..=12).contains(&n) && bl.len() > 1 && bl[1..].chars().all(|c| c.is_ascii_digit()) {
                        KeyCodeDef::F(n)
                    } else { return None; }
                } else { return None; }
            } else if base.chars().count() == 1 {
                let c = base.chars().next().unwrap();
                if matches!(c, ' ' | '-' | ':' | '[' | '\\') { return None; }
                if c.is_ascii_uppercase() {
                    kd.shift = true;
                    KeyCodeDef::Char(c.to_ascii_lowercase())
                } else {
                    KeyCodeDef::Char(c)
                }
            } else {
                return None;
            }
        }
    };
    if matches!(kd.code, KeyCodeDef::BackTab) { kd.shift = true; }
    Some(kd)
}

pub fn parse_keymap_entry(spec: &str) -> Option<(KeyDef, Action)> {
    let parts: Vec<&str> = spec.split('=').collect();
    if parts.len() != 2 { return None; }
    let key = parse_key(parts[0].trim())?;
    let action = action_from_name(parts[1].trim())?;
    Some((key, action))
}

#[derive(Clone, Debug)]
pub struct KeyMap {
    pub map: HashMap<KeyDef, Action>,
}

impl KeyMap {
    pub fn new(custom: &[String]) -> Result<Self, ()> {
        let mut map: HashMap<KeyDef, Action> = HashMap::new();
        let defaults: &[(&str, &str)] = &[
            ("up", "up"), ("down", "down"), ("alt-right", "scroll_right"),
            ("shift-alt-right", "scroll_horizontal_end"), ("alt-left", "scroll_left"),
            ("shift-alt-left", "scroll_horizontal_home"), ("pageup", "page_up"),
            ("pagedown", "page_down"), ("home", "move_top"), ("end", "move_end"),
            ("tab", "toggle_forcus"), ("left", "forcus_watch_pane"), ("right", "forcus_history_pane"),
            ("q", "quit"), ("esc", "reset"), ("ctrl-c", "cancel"), ("h", "help"),
            ("c", "toggle_color"), ("n", "toggle_line_number"), ("r", "toggle_reverse"),
            ("m", "toggle_mouse_support"), ("t", "toggle_view_header_pane"),
            ("backspace", "toggle_view_history_pane"), ("b", "toggle_border"),
            ("d", "toggle_diff_mode"), ("0", "set_diff_mode_plane"), ("1", "set_diff_mode_watch"),
            ("2", "set_diff_mode_line"), ("3", "set_diff_mode_word"), ("shift-o", "set_diff_only"),
            ("o", "toggle_output_mode"), ("f3", "set_output_mode_output"), ("f1", "set_output_mode_stdout"),
            ("f2", "set_output_mode_stderr"), ("w", "toggle_wrap_mode"), ("ctrl-n", "next_keyword"),
            ("ctrl-p", "prev_keyword"), ("shift-s", "toggle_history_summary"), ("plus", "interval_plus"),
            ("minus", "interval_minus"), ("p", "toggle_pause"), ("/", "change_filter_mode"),
            ("*", "change_regex_filter_mode"), ("mouse-scroll_up", "mouse_scroll_up"),
            ("mouse-scroll_down", "mouse_scroll_down"), ("mouse-button_down_left", "mouse_button_left"),
        ];
        for (k, a) in defaults {
            let kd = parse_key(k).ok_or(())?;
            let act = action_from_name(a).ok_or(())?;
            map.insert(kd, act);
        }
        for spec in custom {
            let (kd, act) = parse_keymap_entry(spec).ok_or(())?;
            map.insert(kd, act);
        }
        Ok(Self { map })
    }

    pub fn get(&self, key: &KeyDef) -> Option<Action> { self.map.get(key).copied() }

    pub fn keys_for_action(&self, action: Action) -> Vec<KeyDef> {
        self.map.iter().filter(|(_, a)| **a == action).map(|(k, _)| *k).collect()
    }
}
