#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct SStyle {
    pub fg: Option<Col>,
    pub bg: Option<Col>,
    pub bold: bool,
    pub dim: bool,
    pub italic: bool,
    pub underline: bool,
    pub reverse: bool,
