fn col_fg(c: Col) -> String {
    match c {
        Col::Reset => "39".to_string(),
        Col::Black => "30".to_string(),
        Col::Red => "31".to_string(),
        Col::Green => "32".to_string(),
        Col::Yellow => "33".to_string(),
        Col::Blue => "34".to_string(),
        Col::Magenta => "35".to_string(),
        Col::Cyan => "36".to_string(),
        Col::Gray => "37".to_string(),
        Col::DarkGray => "38;5;240".to_string(),
        Col::White => "97".to_string(),
        Col::Indexed(n) => format!("38;5;{}", n),
        Col::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
    }
}
fn col_bg(c: Col) -> String {
    match c {
        Col::Reset => "49".to_string(),
        Col::Black => "40".to_string(),
        Col::Red => "41".to_string(),
        Col::Green => "42".to_string(),
        Col::Yellow => "43".to_string(),
        Col::Blue => "44".to_string(),
        Col::Magenta => "45".to_string(),
        Col::Cyan => "46".to_string(),
        Col::Gray => "47".to_string(),
        Col::DarkGray => "48;5;240".to_string(),
        Col::White => "107".to_string(),
        Col::Indexed(n) => format!("48;5;{}", n),
        Col::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
    }
