struct AnsiState { style: SStyle }

impl AnsiState {
    fn apply_sgr(&mut self, params: &[i64]) {
        if params.is_empty() { self.style = SStyle::default(); return; }
        let mut i = 0;
        while i < params.len() {
            let p = params[i];
            match p {
                0 => self.style = SStyle::default(),
                1 => self.style.bold = true,
                2 => self.style.dim = true,
                3 => self.style.italic = true,
                4 => self.style.underline = true,
                7 => self.style.reverse = true,
                22 => { self.style.bold = false; self.style.dim = false; }
                23 => self.style.italic = false,
                24 => self.style.underline = false,
                27 => self.style.reverse = false,
                30..=37 => self.style.fg = Some(named_color((p - 30) as u8)),
                38 => {
                    if i + 2 < params.len() && params[i + 1] == 5 {
                        self.style.fg = Some(Col::Indexed(params[i + 2] as u8)); i += 2;
                    } else if i + 4 < params.len() && params[i + 1] == 2 {
                        self.style.fg = Some(Col::Rgb(params[i + 2] as u8, params[i + 3] as u8, params[i + 4] as u8)); i += 4;
                    }
                }
                39 => self.style.fg = None,
                40..=47 => self.style.bg = Some(named_color((p - 40) as u8)),
                48 => {
                    if i + 2 < params.len() && params[i + 1] == 5 {
                        self.style.bg = Some(Col::Indexed(params[i + 2] as u8)); i += 2;
                    } else if i + 4 < params.len() && params[i + 1] == 2 {
                        self.style.bg = Some(Col::Rgb(params[i + 2] as u8, params[i + 3] as u8, params[i + 4] as u8)); i += 4;
                    }
                }
                49 => self.style.bg = None,
                90..=97 => self.style.fg = Some(Col::Indexed((p - 90 + 8) as u8)),
                100..=107 => self.style.bg = Some(Col::Indexed((p - 100 + 8) as u8)),
                _ => {}
            }
            i += 1;
        }
    }
}

fn named_color(n: u8) -> Col {
    match n { 0 => Col::Black, 1 => Col::Red, 2 => Col::Green, 3 => Col::Yellow, 4 => Col::Blue, 5 => Col::Magenta, 6 => Col::Cyan, _ => Col::Gray }
}

/// Parse a single raw line (escape sequences included) into spans,
/// carrying SGR state across calls through `state_out`.
fn parse_ansi_line(line: &str, state: &mut AnsiState) -> Vec<Span> {
    let mut spans: Vec<Span> = Vec::new();
    let mut cur = String::new();
    let mut chars = line.chars().peekable();
    let flush = |cur: &mut String, spans: &mut Vec<Span>, style: SStyle| {
        if !cur.is_empty() {
            spans.push(Span::new(std::mem::take(cur), style));
        }
    };
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            // Collect a CSI sequence.
            let mut seq: Vec<char> = Vec::new();
            let mut is_csi = false;
            if chars.peek() == Some(&'[') {
                chars.next();
                is_csi = true;
                for cc in chars.by_ref() {
                    if ('@'..='~').contains(&cc) { seq.push(cc); break; }
                    seq.push(cc);
                }
            } else if chars.peek() == Some(&']') {
                // OSC: consume until BEL or ST.
                chars.next();
                let mut prev = '\0';
                for cc in chars.by_ref() {
                    if cc == '\x07' || (prev == '\x1b' && cc == '\\') { break; }
                    prev = cc;
                }
                continue;
            } else {
                // Two-character escape: drop the next character.
                let _ = chars.next();
                continue;
            }
            if is_csi {
                let finalc = seq.last().copied().unwrap_or(' ');
                if finalc == 'm' {
                    flush(&mut cur, &mut spans, state.style);
                    let body: String = seq[..seq.len().saturating_sub(1)].iter().collect();
                    let params: Vec<i64> = if body.is_empty() { vec![0] } else {
                        body.split(';').map(|p| p.parse::<i64>().unwrap_or(0)).collect()
                    };
                    state.apply_sgr(&params);
                }
                // Other CSI sequences are ignored (stripped).
            }
            continue;
        }
        cur.push(c);
    }
    flush(&mut cur, &mut spans, state.style);
    if spans.is_empty() { spans.push(Span::plain("")); }
    spans
}

pub fn parse_ansi_lines(lines: &[String]) -> Vec<Vec<Span>> {
    let mut st = AnsiState { style: SStyle::default() };
    lines.iter().map(|l| parse_ansi_line(l, &mut st)).collect()
}

pub fn strip_ansi_lines(lines: &[String]) -> Vec<String> {
    parse_ansi_lines(lines).iter().map(|spans| spans.iter().map(|s| s.text.clone()).collect()).collect()
