fn escape_esc(line: &str) -> String { line.replace('\x1b', "\\x1b") }

// ---------- diff algorithms ----------

fn split_inclusive_lines(text: &str) -> Vec<String> {
    if text.is_empty() { return Vec::new(); }
    let mut out = Vec::new();
    let mut start = 0;
    for (i, c) in text.char_indices() {
        if c == '\n' {
            out.push(text[start..=i].to_string());
            start = i + 1;
        }
    }
    if start < text.len() { out.push(text[start..].to_string()); }
    out
}

#[derive(Clone, Debug, PartialEq)]
enum Op { Eq(String), Del(String), Ins(String) }

/// A standard Myers O(ND) diff over tokens.
fn myers_diff(a: &[String], b: &[String]) -> Vec<Op> {
    let n = a.len();
    let m = b.len();
    if n == 0 { return b.iter().map(|x| Op::Ins(x.clone())).collect(); }
    if m == 0 { return a.iter().map(|x| Op::Del(x.clone())).collect(); }
    let max = (n + m) as isize;
    let offset = max;
    let width = (2 * max + 1) as usize;
    let mut trace: Vec<Vec<isize>> = Vec::new();
    let mut v = vec![0isize; width];
    let mut found_d: Option<isize> = None;
    'outer: for d in 0..=max {
        trace.push(v.clone());
        let mut k = -d;
        while k <= d {
            let idx = (k + offset) as usize;
            let mut x = if k == -d || (k != d && v[idx - 1] < v[idx + 1]) { v[idx + 1] } else { v[idx - 1] + 1 };
            let mut y = x - k;
            while (x as usize) < n && (y as usize) < m && a[x as usize] == b[y as usize] {
                x += 1; y += 1;
            }
            v[idx] = x;
            if x as usize >= n && y as usize >= m {
                found_d = Some(d);
                break 'outer;
            }
            k += 2;
        }
    }
    let d_final = found_d.unwrap_or(max);
    // Backtrack.
    let mut ops: Vec<Op> = Vec::new();
    let mut x = n as isize;
    let mut y = m as isize;
    for d in (0..=d_final).rev() {
        let vv = &trace[d as usize];
        let k = x - y;
        let idx = |kk: isize| (kk + offset) as usize;
        let prev_k = if k == -d || (k != d && vv[idx(k - 1)] < vv[idx(k + 1)]) { k + 1 } else { k - 1 };
        let prev_x = vv[idx(prev_k)];
        let prev_y = prev_x - prev_k;
        while x > prev_x && y > prev_y {
            ops.push(Op::Eq(a[(x - 1) as usize].clone()));
            x -= 1; y -= 1;
        }
        if d == 0 { break; }
        if x == prev_x {
            ops.push(Op::Ins(b[(y - 1) as usize].clone()));
            y -= 1;
        } else {
            ops.push(Op::Del(a[(x - 1) as usize].clone()));
            x -= 1;
        }
    }
    ops.reverse();
    ops
}

fn tokenize_words(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut cur_ws: Option<bool> = None;
    for c in s.chars() {
        let ws = c.is_whitespace();
        match cur_ws {
            Some(w) if w == ws => cur.push(c),
            _ => {
                if !cur.is_empty() { out.push(std::mem::take(&mut cur)); }
                cur.push(c);
                cur_ws = Some(ws);
            }
        }
    }
    if !cur.is_empty() { out.push(cur); }
    out
}

/// Word-token diff for a paired old/new line: returns (old segments, new segments)
/// where each segment is (text, is_changed).
fn word_segments(old: &str, new: &str) -> (Vec<(String, bool)>, Vec<(String, bool)>) {
    let a = tokenize_words(old);
    let b = tokenize_words(new);
    let ops = myers_diff(&a, &b);
    let mut o = Vec::new();
    let mut n = Vec::new();
    for op in ops {
        match op {
            Op::Eq(t) => { o.push((t.clone(), false)); n.push((t, false)); }
            Op::Del(t) => o.push((t, true)),
            Op::Ins(t) => n.push((t, true)),
        }
    }
    (o, n)
}

fn trim_token_nl(s: &str) -> String { s.trim_end_matches('\n').trim_end_matches('\r').to_string() }

/// Build diff display lines (Line or Word mode), without line numbers/reverse.
fn build_diff_lines(
    settings: &Settings,
    cur_lines_txt: &[String],
    prev_lines_txt: &[String],
) -> Vec<DisplayLine> {
    let old_joined = prev_lines_txt.join("\n");
    let new_joined = cur_lines_txt.join("\n");
    let old_toks = split_inclusive_lines(&old_joined);
    let new_toks = split_inclusive_lines(&new_joined);
    let raw_ops = myers_diff(&old_toks, &new_toks);

    // Group into blocks: equals separated; inside a change block put all
    // deletions before insertions.
    #[derive(Debug)]
    enum Block { Eq(Vec<String>), Change { dels: Vec<String>, inss: Vec<String> } }
    let mut blocks: Vec<Block> = Vec::new();
    for op in raw_ops {
        match op {
            Op::Eq(t) => {
                if let Some(Block::Eq(v)) = blocks.last_mut() { v.push(trim_token_nl(&t)); }
                else { blocks.push(Block::Eq(vec![trim_token_nl(&t)])); }
            }
            Op::Del(t) => {
                if let Some(Block::Change { dels, .. }) = blocks.last_mut() { dels.push(trim_token_nl(&t)); }
                else { blocks.push(Block::Change { dels: vec![trim_token_nl(&t)], inss: Vec::new() }); }
            }
            Op::Ins(t) => {
                if let Some(Block::Change { inss, .. }) = blocks.last_mut() { inss.push(trim_token_nl(&t)); }
                else { blocks.push(Block::Change { dels: Vec::new(), inss: vec![trim_token_nl(&t)] }); }
            }
        }
    }

    let red = SStyle::fg(Col::Red);
    let green = SStyle::fg(Col::Green);
    let word_mode = settings.differences == DiffMode::Word;

    let mut out: Vec<DisplayLine> = Vec::new();
    let mut old_no: usize = 1;
    let mut new_no: usize = 1;
    // Number values are attached later; store them in a parallel vector via
    // a wrapper: we encode them into DisplayLine through a thread-local-ish
    // approach: instead we return them by encoding in kind + a map. Simpler:
    // callers recompute numbers from kinds; but paired numbering needs the
    // counters, so we stash them in spans later in build_text. Here we only
    // need ordering; numbers are added by build_text using the same walk:
    // To avoid duplication, build_text calls this and then renumbers by
    // scanning kinds (Equal/Delete consume old, Insert consumes new).
    let _ = (&mut old_no, &mut new_no);

    for block in blocks {
        match block {
            Block::Eq(lines) => {
                for l in lines {
                    let spans = vec![Span::plain(format!("   {}", l))];
                    out.push(DisplayLine { spans, kind: LineKind::Equal });
                }
            }
            Block::Change { dels, inss } => {
                let pairs = std::cmp::max(dels.len(), inss.len());
                for i in 0..dels.len() {
                    let l = &dels[i];
                    let mut spans = vec![Span::new("-  ", red)];
                    if i < inss.len() {
                        let (segs, _) = word_segments(l, &inss[i]);
                        for (txt, changed) in segs {
                            let mut st = red;
                            if word_mode && changed { st.bg = Some(Col::White); st.reverse = true; }
                            spans.push(Span::new(txt, st));
                        }
                        spans.push(Span::new("", red));
                    } else {
                        spans.push(Span::new(l.clone(), red));
                    }
                    out.push(DisplayLine { spans, kind: LineKind::Delete });
                }
                for i in 0..inss.len() {
                    let l = &inss[i];
                    let mut spans = vec![Span::new("+  ", green)];
                    if i < dels.len() {
                        let (_, segs) = word_segments(&dels[i], l);
                        for (txt, changed) in segs {
                            let mut st = green;
                            if word_mode && changed { st.bg = Some(Col::White); st.reverse = true; }
                            spans.push(Span::new(txt, st));
                        }
                        spans.push(Span::new("", green));
                    } else {
                        spans.push(Span::new(l.clone(), green));
                    }
                    out.push(DisplayLine { spans, kind: LineKind::Insert });
                }
                let _ = pairs;
            }
        }
    }
    out
}

// ---------- main text builder ----------

pub struct BuiltText {
    pub lines: Vec<DisplayLine>,
}

fn add_line_numbers(lines: &mut Vec<DisplayLine>, settings: &Settings, max_number: usize) {
    if !settings.line_number { return; }
    let width = max_number.to_string().len();
    let mut old_no: usize = 1;
    let mut new_no: usize = 1;
    let is_diff = matches!(settings.differences, DiffMode::Line | DiffMode::Word);
    for line in lines.iter_mut() {
        let num = if is_diff {
            match line.kind {
                LineKind::Equal => { let v = old_no; old_no += 1; new_no += 1; v }
                LineKind::Delete => { let v = old_no; old_no += 1; v }
                LineKind::Insert => { let v = new_no; new_no += 1; v }
                LineKind::Normal => { let v = new_no; new_no += 1; v }
            }
        } else {
            let v = new_no; new_no += 1; v
        };
        let digits = num.to_string();
        let mut prefix: Vec<Span> = Vec::new();
        if width > digits.len() {
            prefix.push(Span::plain(" ".repeat(width - digits.len())));
        }
        let num_style = SStyle::fg(Col::DarkGray);
        prefix.push(Span::new(digits, num_style));
        prefix.push(Span::new(" | ", num_style));
        prefix.extend(line.spans.drain(..));
        line.spans = prefix;
    }
}

pub fn build_text(
    settings: &Settings,
    cur: &CommandResultData,
    prev: &CommandResultData,
) -> BuiltText {
    build_text_for(settings, cur, prev, false)
}

/// `batch` changes the plain-mode line splitting (a trailing empty line is
/// kept) to mirror the reference batch printer.
pub fn build_text_for(
    settings: &Settings,
    cur: &CommandResultData,
    prev: &CommandResultData,
    batch: bool,
) -> BuiltText {
    let cur_src = settings.output_text(cur, settings.output).to_string();
    let prev_src = settings.output_text(prev, settings.output).to_string();

    let cur_raw = logical_lines(&cur_src);
    let prev_raw = logical_lines(&prev_src);

    let cur_expanded: Vec<String> = cur_raw.iter().map(|l| expand_tabs(l, settings.tab_size)).collect();
    let prev_expanded: Vec<String> = prev_raw.iter().map(|l| expand_tabs(l, settings.tab_size)).collect();

    let mut lines: Vec<DisplayLine> = Vec::new();
    let mut max_number: usize;

    match settings.differences {
        DiffMode::Line | DiffMode::Word => {
            let cur_txt = if settings.color { strip_ansi_lines(&cur_expanded) } else { cur_expanded.iter().map(|l| escape_esc(l)).collect::<Vec<_>>() };
            let prev_txt = if settings.color { strip_ansi_lines(&prev_expanded) } else { prev_expanded.iter().map(|l| escape_esc(l)).collect::<Vec<_>>() };
            lines = build_diff_lines(settings, &cur_txt, &prev_txt);
            if settings.diff_output_only {
                lines.retain(|l| l.kind != LineKind::Equal);
            }
            max_number = std::cmp::max(prev_txt.len(), cur_txt.len());
            add_line_numbers(&mut lines, settings, max_number);
        }
        DiffMode::Watch => {
            // Character-position comparison per line.
            let (cur_styled, cur_plain, prev_plain) = if settings.color {
                let parsed = parse_ansi_lines(&cur_expanded);
                let cp = parsed.iter().map(|sp| sp.iter().map(|s| s.text.clone()).collect::<String>()).collect::<Vec<_>>();
                let pp = strip_ansi_lines(&prev_expanded);
                (Some(parsed), cp, pp)
            } else {
                let cp = cur_expanded.iter().map(|l| escape_esc(l)).collect::<Vec<_>>();
                let pp = prev_expanded.iter().map(|l| escape_esc(l)).collect::<Vec<_>>();
                (None, cp, pp)
            };
            max_number = cur_plain.len();
            for (i, plain) in cur_plain.iter().enumerate() {
                let prev_line = prev_plain.get(i).map(|s| s.as_str()).unwrap_or("");
                let prev_chars: Vec<char> = prev_line.chars().collect();
                let mut spans: Vec<Span> = Vec::new();
                if let Some(parsed) = &cur_styled {
                    let mut idx: usize = 0;
                    for sp in &parsed[i] {
                        for ch in sp.text.chars() {
                            let same = prev_chars.get(idx).map(|c| *c == ch).unwrap_or(false);
                            let mut st = sp.style;
                            if !same { st.reverse = true; }
                            spans.push(Span::new(ch.to_string(), st));
                            idx += 1;
                        }
                    }
                    if spans.is_empty() { spans.push(Span::plain("")); }
                } else {
                    for (idx, ch) in plain.chars().enumerate() {
                        let same = prev_chars.get(idx).map(|c| *c == ch).unwrap_or(false);
                        let st = if same { SStyle::default() } else { SStyle { reverse: true, ..Default::default() } };
                        spans.push(Span::new(ch.to_string(), st));
                    }
                    if spans.is_empty() { spans.push(Span::plain("")); }
                }
                lines.push(DisplayLine { spans, kind: LineKind::Normal });
            }
            add_line_numbers(&mut lines, settings, max_number);
        }
        DiffMode::None => {
            if batch {
                // Batch plain mode splits on '\n' (keeping the trailing
                // empty piece) before numbering/rendering.
                let raw_lines: Vec<String> = cur_src.split('\n').map(|s| s.to_string()).collect();
                let expanded: Vec<String> = raw_lines.iter().map(|l| expand_tabs(l, settings.tab_size)).collect();
                max_number = expanded.len();
                if settings.color {
                    let parsed = parse_ansi_lines(&expanded);
                    for spans in parsed { lines.push(DisplayLine { spans, kind: LineKind::Normal }); }
                } else if settings.reverse {
                    // Reverse is handled generically below using logical
                    // lines; batch reverse was observed on split lines, so
                    // build from the split lines directly here.
                    for l in &expanded {
                        lines.push(DisplayLine { spans: vec![Span::plain(escape_esc(l))], kind: LineKind::Normal });
                    }
                    add_line_numbers(&mut lines, settings, max_number);
                    lines.reverse();
                    return BuiltText { lines };
                } else {
                    for l in &expanded {
                        lines.push(DisplayLine { spans: vec![Span::plain(escape_esc(l))], kind: LineKind::Normal });
                    }
                }
                add_line_numbers(&mut lines, settings, max_number);
                return BuiltText { lines };
            }
            max_number = cur_expanded.len();
            if settings.color {
                let parsed = parse_ansi_lines(&cur_expanded);
                for spans in parsed { lines.push(DisplayLine { spans, kind: LineKind::Normal }); }
            } else {
                for l in &cur_expanded {
                    lines.push(DisplayLine { spans: vec![Span::plain(escape_esc(l))], kind: LineKind::Normal });
                }
            }
            add_line_numbers(&mut lines, settings, max_number);
        }
    }

    if settings.reverse {
        lines.reverse();
    }
    BuiltText { lines }
}

// ---------- summaries ----------

pub fn summary_counts(
    settings: &Settings,
    cur: &CommandResultData,
    prev: &CommandResultData,
) -> (usize, usize, usize, usize) {
    let cur_src = settings.output_text(cur, settings.output);
    let prev_src = settings.output_text(prev, settings.output);
    let cur_lines = logical_lines(cur_src);
    let prev_lines = logical_lines(prev_src);
    // A completely empty source contributes no lines for counting.
    let cur_count_lines: Vec<String> = if cur_src.is_empty() { Vec::new() } else { cur_lines.clone() };
    let prev_count_lines: Vec<String> = if prev_src.is_empty() { Vec::new() } else { prev_lines.clone() };
    let ops = myers_diff(&prev_count_lines, &cur_count_lines);
    let mut ladd = 0; let mut ldel = 0;
    for op in &ops {
        match op { Op::Ins(_) => ladd += 1, Op::Del(_) => ldel += 1, _ => {} }
    }
    let a_chars: Vec<String> = prev_src.chars().map(|c| c.to_string()).collect();
    let b_chars: Vec<String> = cur_src.chars().map(|c| c.to_string()).collect();
    let cops = myers_diff(&a_chars, &b_chars);
    let mut cadd = 0; let mut cdel = 0;
    for op in &cops {
        match op { Op::Ins(_) => cadd += 1, Op::Del(_) => cdel += 1, _ => {} }
    }
    (ladd, ldel, cadd, cdel)
}

// ---------- batch ANSI conversion ----------

fn col_fg(c: Col) -> String {
    match c {
        Col::Reset => "39".to_string(),
        Col::Black => "30".to_string(),
        Col::Red => "31".to_string(),
        Col::Green => "32".to_string(),
        Col::Yellow => "33".to_string(),
        Col::Blue => "34".to_string(),
        Col::Magenta => "35".to_string(),
        Col::Cyan => "36".to_string(),
        Col::Gray => "37".to_string(),
        Col::DarkGray => "38;5;240".to_string(),
        Col::White => "97".to_string(),
        Col::Indexed(n) => format!("38;5;{}", n),
        Col::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
    }
}
fn col_bg(c: Col) -> String {
    match c {
        Col::Reset => "49".to_string(),
        Col::Black => "40".to_string(),
        Col::Red => "41".to_string(),
        Col::Green => "42".to_string(),
        Col::Yellow => "43".to_string(),
        Col::Blue => "44".to_string(),
        Col::Magenta => "45".to_string(),
        Col::Cyan => "46".to_string(),
        Col::Gray => "47".to_string(),
        Col::DarkGray => "48;5;240".to_string(),
        Col::White => "107".to_string(),
        Col::Indexed(n) => format!("48;5;{}", n),
        Col::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
    }
}

pub fn span_to_ansi(span: &Span) -> String {
    let st = span.style;
    if st == SStyle::default() { return span.text.clone(); }
    let mut codes: Vec<String> = Vec::new();
    let (mut fg, mut bg) = (st.fg, st.bg);
    let mut reverse = st.reverse;
    if reverse && (fg.is_some() || bg.is_some()) {
        // Emphasised (word-diff) spans are emitted with swapped colours.
        let nf = bg.map(|c| match c { Col::White => Col::Gray, other => other });
        let nb = fg;
        fg = nf;
        bg = nb;
        reverse = false;
    }
    if st.bold { codes.push("1".to_string()); }
    if st.dim { codes.push("2".to_string()); }
    if st.italic { codes.push("3".to_string()); }
    if st.underline { codes.push("4".to_string()); }
    if reverse { codes.push("7".to_string()); }
    if let Some(c) = fg { codes.push(col_fg(c)); }
    if let Some(c) = bg { codes.push(col_bg(c)); }
    if codes.is_empty() { return span.text.clone(); }
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), span.text)
}

pub fn line_to_ansi(line: &DisplayLine) -> String {
    line.spans.iter().map(span_to_ansi).collect()
}
