fn rt_col(c: Col) -> Color {
    match c {
        Col::Reset => Color::Reset,
        Col::Black => Color::Indexed(0),
        Col::Red => Color::Indexed(1),
        Col::Green => Color::Indexed(2),
        Col::Yellow => Color::Indexed(3),
        Col::Blue => Color::Indexed(4),
        Col::Magenta => Color::Indexed(5),
        Col::Cyan => Color::Indexed(6),
        Col::Gray => Color::Indexed(7),
        Col::DarkGray => Color::Indexed(8),
        Col::White => Color::Indexed(15),
        Col::Indexed(n) => Color::Indexed(n),
        Col::Rgb(r, g, b) => Color::Rgb(r, g, b),
    }
}

fn rt_style(s: SStyle) -> Style {
    let mut st = Style::default();
    if let Some(c) = s.fg { st = st.fg(rt_col(c)); }
    if let Some(c) = s.bg { st = st.bg(rt_col(c)); }
    if s.bold { st = st.add_modifier(Modifier::BOLD); }
    if s.dim { st = st.add_modifier(Modifier::DIM); }
    if s.italic { st = st.add_modifier(Modifier::ITALIC); }
    if s.underline { st = st.add_modifier(Modifier::UNDERLINED); }
    if s.reverse { st = st.add_modifier(Modifier::REVERSED); }
    st
}

fn to_rline(spans: &[Span]) -> RLine<'static> {
    let rspans: Vec<RSpan<'static>> = spans
        .iter()
        .map(|s| RSpan::styled(s.text.clone(), rt_style(s.style)))
        .collect();
    RLine::from(rspans)
}

