        let w = self.last_watch_width.max(1) as usize;
        let mut visual = 0usize;
        for (i, l) in lines.iter().enumerate() {
            if i == logical_idx { break; }
            visual += if self.wrap_on { wrapped_count(&l.text(), w) } else { 1 };
        }
        let h = self.last_watch_height as usize;
        let sy = self.watch_scroll_y as usize;
        if visual < sy {
            self.watch_scroll_y = visual as u16;
        } else if visual >= sy + h {
            self.watch_scroll_y = (visual + 1).saturating_sub(h) as u16;
        }
    }

    fn apply_filter_highlights(&self, lines: &mut Vec<DisplayLine>) {
        if self.filter.is_none() { return; }
        let ms = self.matches(lines);
        if ms.is_empty() { return; }
        let focused = if self.focused_match < ms.len() { self.focused_match } else { 0 };
        // Group matches by line.
        let mut by_line: HashMap<usize, Vec<(usize, usize, usize)>> = HashMap::new();
        for (mi, (li, s, e)) in ms.iter().enumerate() {
            by_line.entry(*li).or_default().push((*s, *e, mi));
        }
        for (li, list) in by_line {
            if li >= lines.len() { continue; }
            let line = &mut lines[li];
            // Flatten to chars with styles.
            let mut chars: Vec<(char, SStyle)> = Vec::new();
            for sp in &line.spans {
                for c in sp.text.chars() { chars.push((c, sp.style)); }
            }
            let mut highlighted: HashSet<usize> = HashSet::new();
            let mut focus_flags: HashMap<usize, bool> = HashMap::new();
            for (s, e, mi) in &list {
                for ci in *s..*e {
                    highlighted.insert(ci);
                    focus_flags.insert(ci, *mi == focused);
                }
            }
            // Rebuild spans grouping consecutive chars with equal effective style.
            let mut new_spans: Vec<Span> = Vec::new();
            for (ci, (c, orig)) in chars.iter().enumerate() {
                let style = if highlighted.contains(&ci) {
                    let is_focus = focus_flags.get(&ci).copied().unwrap_or(false);
                    SStyle {
                        fg: Some(Col::Black),
                        bg: Some(if is_focus { Col::Yellow } else { Col::Cyan }),
                        ..Default::default()
                    }
                } else { *orig };
                if let Some(last) = new_spans.last_mut() {
                    let last_span: &mut Span = last;
                    if last_span.style == style {
                        last_span.text.push(*c);
                        continue;
                    }
                }
                new_spans.push(Span::new(c.to_string(), style));
            }
            if new_spans.is_empty() { new_spans.push(Span::plain("")); }
            line.spans = new_spans;
        }
    }

    // ----- key handling -----

    pub fn handle_action(&mut self, a: Action) {
        // Exit popup has its own dispatch (handled in handle_key before
        // reaching here for the raw keys it intercepts).
        if self.exit_popup {
            match a {
                Action::Quit | Action::Cancel => self.should_quit = true,
                Action::Reset => self.exit_popup = false,
                Action::Help => { self.exit_popup = false; self.help_on = true; }
                _ => {}
            }
            return;
        }
        if self.help_on {
            match a {
                Action::Up => self.help_scroll = self.help_scroll.saturating_sub(1),
                Action::Down => self.help_scroll = self.help_scroll.saturating_add(1),
                Action::PageUp => self.help_scroll = self.help_scroll.saturating_sub(self.last_help_inner_height),
                Action::PageDown => self.help_scroll = self.help_scroll.saturating_add(self.last_help_inner_height),
                Action::MoveTop => self.help_scroll = 0,
                Action::MoveEnd => {
                    let total = self.help_lines().len();
                    let h = self.last_help_inner_height as usize;
                    self.help_scroll = total.saturating_sub(h) as u16;
                }
                Action::Help => self.help_on = false,
                Action::Quit => { self.help_on = false; self.exit_popup = true; }
                Action::Cancel => self.help_on = false,
                _ => {}
            }
            return;
        }

        match a {
            Action::Up | Action::Down | Action::PageUp | Action::PageDown | Action::MoveTop | Action::MoveEnd => {
                self.move_focused_pane(a);
            }
            Action::ScrollRight => self.scroll_right(false),
            Action::ScrollHorizontalEnd => self.scroll_right(true),
            Action::ScrollLeft => { if !self.wrap_on { self.watch_scroll_x = self.watch_scroll_x.saturating_sub(1); } }
            Action::ScrollHorizontalHome => self.watch_scroll_x = 0,
            Action::ToggleForcus => {
                self.focus = match self.focus { FocusPane::History => FocusPane::Watch, FocusPane::Watch => FocusPane::History };
            }
            Action::ForcusWatchPane => self.focus = FocusPane::Watch,
            Action::ForcusHistoryPane => self.focus = FocusPane::History,
            Action::Quit => { self.exit_popup = true; }
            Action::Cancel => { self.exit_popup = true; }
            Action::Reset => {
                if self.filter.is_some() {
                    self.filter = None;
                    self.focused_match = 0;
                } else {
                    self.exit_popup = true;
                }
            }
            Action::Help => { self.help_on = true; self.help_scroll = 0; }
            Action::ToggleColor => self.color_on = !self.color_on,
            Action::ToggleLineNumber => self.line_number_on = !self.line_number_on,
            Action::ToggleReverse => self.reverse_on = !self.reverse_on,
            Action::ToggleMouseSupport => {
                self.mouse_on = !self.mouse_on;
                self.mouse_capture_changed = true;
            }
            Action::ToggleViewHeaderPane => {
                let newv = !self.show_header;
                self.show_header = newv;
                self.show_history = newv;
            }
            Action::ToggleViewHistoryPane => {
                self.show_history = !self.show_history;
                if !self.show_history { self.focus = FocusPane::Watch; }
            }
            Action::ToggleBorder => self.border_on = !self.border_on,
            Action::ToggleDiffMode => self.diff_mode = self.diff_mode.next(),
            Action::SetDiffModePlane => self.diff_mode = DiffMode::None,
            Action::SetDiffModeWatch => self.diff_mode = DiffMode::Watch,
            Action::SetDiffModeLine => self.diff_mode = DiffMode::Line,
            Action::SetDiffModeWord => self.diff_mode = DiffMode::Word,
            Action::SetDiffOnly => self.diff_only = !self.diff_only,
            Action::ToggleOutputMode => self.output_mode = self.output_mode.next(),
            Action::SetOutputModeOutput => self.output_mode = OutputMode::Output,
            Action::SetOutputModeStdout => self.output_mode = OutputMode::Stdout,
            Action::SetOutputModeStderr => self.output_mode = OutputMode::Stderr,
            Action::ToggleWrapMode => {
                self.wrap_on = !self.wrap_on;
                if self.wrap_on { self.watch_scroll_x = 0; }
            }
            Action::NextKeyword => self.focus_match(true),
            Action::PrevKeyword => self.focus_match(false),
            Action::ToggleHistorySummary => self.summary_on = !self.summary_on,
            Action::IntervalPlus => {
                self.interval += 0.5;
                self.control.lock().unwrap().interval = self.interval;
            }
            Action::IntervalMinus => {
                if self.interval - 0.5 > 0.0 {
                    self.interval -= 0.5;
                    self.control.lock().unwrap().interval = self.interval;
                }
            }
            Action::TogglePause => {
                self.paused = !self.paused;
                self.control.lock().unwrap().paused = self.paused;
            }
            Action::ChangeFilterMode => {
                self.filter_edit = Some(FilterEdit {
                    kind: FilterKind::Keyword,
                    text: self.filter.as_ref().map(|f| f.text.clone()).unwrap_or_default(),
                    had_existing: self.filter.is_some(),
                    prev: self.filter.clone(),
                });
            }
            Action::ChangeRegexFilterMode => {
                self.filter_edit = Some(FilterEdit {
                    kind: FilterKind::Regex,
                    text: self.filter.as_ref().map(|f| f.text.clone()).unwrap_or_default(),
                    had_existing: self.filter.is_some(),
                    prev: self.filter.clone(),
                });
            }
            Action::MouseScrollUp | Action::MouseScrollDown | Action::MouseButtonLeft => {}
        }
    }

    fn filter_edit_key(&mut self, key: &KeyEvent) {
        match key.code {
            KeyCode::Enter => {
                if let Some(edit) = self.filter_edit.take() {
                    self.filter = Some(Filter { kind: edit.kind, text: edit.text });
                    self.focused_match = 0;
                    // Move to the first match, mirroring Enter behaviour.
                    let built = self.built_text();
                    let ms = self.matches(&built.lines);
                    if !ms.is_empty() {
                        self.scroll_to_match(&built.lines, ms[0].0);
                    }
                }
            }
            KeyCode::Backspace => {
                if let Some(edit) = &mut self.filter_edit { edit.text.pop(); }
            }
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(edit) = self.filter_edit.take() {
                    self.filter = edit.prev;
                }
            }
            KeyCode::Char(c) => {
                if let Some(edit) = &mut self.filter_edit { edit.text.push(c); }
            }
            _ => {}
        }
    }

    pub fn handle_key(&mut self, key: KeyEvent) {
        if key.kind == KeyEventKind::Release { return; }

        // Filter editing is modal.
        if self.filter_edit.is_some() {
            self.filter_edit_key(&key);
            return;
        }

        // Raw keys intercepted by the exit popup.
        if self.exit_popup {
            match key.code {
                KeyCode::Char('y') | KeyCode::Char('q') => { self.should_quit = true; return; }
                KeyCode::Char('n') => { self.exit_popup = false; return; }
                KeyCode::Esc => { self.exit_popup = false; return; }
                _ => {}
            }
        }

        let kd = keydef_from_event(&key);
        if let Some(action) = self.keymap.get(&kd) {
            self.handle_action(action);
        }
    }

    pub fn handle_mouse(&mut self, ev: MouseEvent, layout: &LayoutInfo) {
        let kd = match ev.kind {
            MouseEventKind::ScrollUp => KeyDef::simple(KeyCodeDef::MouseScrollUp),
            MouseEventKind::ScrollDown => KeyDef::simple(KeyCodeDef::MouseScrollDown),
            MouseEventKind::ScrollLeft => KeyDef::simple(KeyCodeDef::MouseScrollLeft),
            MouseEventKind::ScrollRight => KeyDef::simple(KeyCodeDef::MouseScrollRight),
            MouseEventKind::Down(MouseButton::Left) => KeyDef::simple(KeyCodeDef::MouseButtonLeft),
            MouseEventKind::Down(MouseButton::Right) => KeyDef::simple(KeyCodeDef::MouseButtonRight),
            _ => return,
        };
        let Some(action) = self.keymap.get(&kd) else { return };
        if self.exit_popup || self.help_on { return; }
        match action {
            Action::MouseScrollUp | Action::MouseScrollDown => {
                let down = action == Action::MouseScrollDown;
                if layout.in_history(ev.column, ev.row) {
                    if down { self.history_down(); } else { self.history_up(); }
                } else if layout.in_watch(ev.column, ev.row) {
                    if down {
                        let built = self.built_text();
                        let total = self.visual_total(&built.lines);
                        let max = self.max_watch_scroll(total);
                        self.watch_scroll_y = std::cmp::min(self.watch_scroll_y.saturating_add(2), max);
                    } else {
                        self.watch_scroll_y = self.watch_scroll_y.saturating_sub(2);
                    }
                }
            }
            Action::MouseButtonLeft => {
                if layout.in_history(ev.column, ev.row) {
                    if let Some(sel) = layout.history_click(ev.row, &self.history_row_map, self.history_scroll_offset) {
                        self.selection = sel;
                        self.reset_watch_scroll();
                    }
                }
            }
            other => self.handle_action(other),
        }
    }

    fn help_lines(&self) -> Vec<(String, String)> {
        // (key display, description)
        let mut out = Vec::new();
        for (action, _name, desc) in ACTION_INFO.iter() {
            for kd in self.keymap.keys_for_action(*action) {
                out.push((kd.to_display(), desc.to_string()));
            }
        }
        out
    }

    // ----- drawing -----

    pub fn draw(&mut self, f: &mut Frame) {
        let area = f.area();
        let layout = compute_layout(area, self.show_header, self.show_history, self.border_on);
        self.last_watch_width = layout.watch.width;
        self.last_watch_height = layout.watch.height;
        self.last_body_height = layout.body.height;

        // Header
        if self.show_header {
            self.draw_header(f, &layout);
        }
        // Watch
        self.draw_watch(f, &layout);
        // History
        if layout.history.width > 0 {
            self.draw_history(f, &layout);
        }
        // Border lines
        if self.border_on {
            self.draw_border(f, &layout);
        }
        // Popups
        if self.help_on {
            self.draw_help(f, area);
        }
        if self.exit_popup {
            self.draw_exit(f, area);
        }
    }

    fn draw_header(&mut self, f: &mut Frame, layout: &LayoutInfo) {
        let area = layout.header;
        let buf = f.buffer_mut();
        // Line 0
        let interval_str = if self.paused { "Paused".to_string() } else { format!("{:.3}", self.interval) };
        let prefix = format!("Every {:>9}:", interval_str);
        let cmd = self.latest_result.command.clone();
        let ts = self.latest_result.timestamp.clone();
        let cmd_style = SStyle::fg(if self.latest_result.status { Col::Green } else { Col::Red });

        let mut line0_spans: Vec<Span> = Vec::new();
        // "Every " plain, interval cyan, ':' plain.
        line0_spans.push(Span::plain("Every "));
        let iv_text: String = prefix.chars().skip(6).take(9).collect();
        line0_spans.push(Span::new(iv_text, SStyle::fg(Col::Cyan)));
        line0_spans.push(Span::plain(":"));

        if !self.has_received {
            if !cmd.is_empty() {
                line0_spans.push(Span::new(cmd.clone(), cmd_style));
            }
            if !self.settings.no_help_banner {
                line0_spans.push(Span::plain(" "));
                line0_spans.push(Span::new("Display help with h key!", SStyle { reverse: true, ..Default::default() }));
            }
            if !ts.is_empty() {
                line0_spans.push(Span::plain(" "));
                line0_spans.push(Span::new(ts.clone(), SStyle::fg(Col::Cyan)));
            }
            let rline = to_rline(&line0_spans);
            buf.set_line(area.x, area.y, &rline, area.width);
        } else {
            // Padded layout: command field fills space before the banner.
            let right_len = (if self.settings.no_help_banner { 0 } else { 24 + 1 }) + ts.len();
            let avail = (area.width as usize).saturating_sub(1);
            let cmd_field = avail.saturating_sub(16 + 1 + right_len);
            let mut cmd_text = cmd.clone();
            if cmd_field > cmd_text.chars().count() {
                cmd_text.push_str(&" ".repeat(cmd_field - cmd_text.chars().count()));
            }
            line0_spans.push(Span::new(cmd_text, cmd_style));
            line0_spans.push(Span::plain(" "));
            if !self.settings.no_help_banner {
                line0_spans.push(Span::new("Display help with h key!", SStyle { reverse: true, ..Default::default() }));
                line0_spans.push(Span::plain(" "));
            }
            line0_spans.push(Span::new(ts.clone(), SStyle::fg(Col::Cyan)));
            let rline = to_rline(&line0_spans);
            buf.set_line(area.x, area.y, &rline, area.width);
        }

        // Line 1: filter / indicators
        let y = area.y + 1;
        let indicator_len = 58usize;
        let left_field = (area.width as usize).saturating_sub(indicator_len + 1);
        // Filter display
        let filter_display: Option<(char, String, bool)> = if let Some(edit) = &self.filter_edit {
            let p = if edit.had_existing { ' ' } else { match edit.kind { FilterKind::Keyword => '/', FilterKind::Regex => '*' } };
            Some((p, edit.text.clone(), true))
        } else if let Some(flt) = &self.filter {
            let p = match flt.kind { FilterKind::Keyword => '/', FilterKind::Regex => '*' };
            Some((p, flt.text.clone(), false))
        } else { None };

        let mut x = area.x;
        if let Some((p, text, _editing)) = &filter_display {
            let buf = f.buffer_mut();
            let pspan = to_rline(&[Span::new(p.to_string(), SStyle::fg(Col::Gray))]);
            let (nx, _) = buf.set_line(x, y, &pspan, 1);
            x = nx;
            let textw = text.chars().count();
            let field_inner = left_field.saturating_sub(1);
            let mut t = text.clone();
            if textw < field_inner { t.push_str(&" ".repeat(field_inner - textw)); }
            let tspan = to_rline(&[Span::new(t, SStyle { fg: Some(Col::Cyan), bold: true, ..Default::default() })]);
            let (nx2, _) = buf.set_line(x, y, &tspan, area.width.saturating_sub(x - area.x));
            x = nx2;
        } else {
            x = area.x + left_field as u16;
        }

        // Indicators
        let items: Vec<(String, Option<SStyle>)> = vec![
            ("Number".to_string(), if self.line_number_on { Some(SStyle { fg: Some(Col::Green), bold: true, reverse: true, ..Default::default() }) } else { None }),
            ("Color".to_string(), if self.color_on { Some(SStyle { fg: Some(Col::Green), bold: true, reverse: true, ..Default::default() }) } else { None }),
            ("Reverse".to_string(), if self.reverse_on { Some(SStyle { fg: Some(Col::Green), bold: true, reverse: true, ..Default::default() }) } else { None }),
            (self.output_mode.label().to_string(), Some(SStyle { fg: Some(Col::Yellow), reverse: true, ..Default::default() })),
            (match self.focus { FocusPane::History => "History".to_string(), FocusPane::Watch => "Watch  ".to_string() },
             Some(SStyle { fg: Some(Col::Cyan), reverse: true, ..Default::default() })),
            (self.diff_label(), Some(SStyle { fg: Some(Col::Magenta), reverse: true, ..Default::default() })),
        ];
        let buf = f.buffer_mut();
        for (i, (label, style)) in items.iter().enumerate() {
            if i > 0 {
                let sp = to_rline(&[Span::plain(" ")]);
                let (nx, _) = buf.set_line(x, y, &sp, 1);
                x = nx;
            }
            let mut spans = vec![Span::plain("[")];
            match style {
                Some(st) => spans.push(Span::new(label.clone(), *st)),
                None => spans.push(Span::plain(label.clone())),
            }
            spans.push(Span::plain("]"));
            let rl = to_rline(&spans);
            let (nx, _) = buf.set_line(x, y, &rl, area.width.saturating_sub(x - area.x));
            x = nx;
        }
    }

    fn diff_label(&self) -> String {
        if self.diff_only {
            match self.diff_mode {
                DiffMode::Line => return "Line(Only)".to_string(),
                DiffMode::Word => return "Word(Only)".to_string(),
                _ => {}
            }
        }
        format!("{:<10}", self.diff_mode.label())
    }

    fn draw_watch(&mut self, f: &mut Frame, layout: &LayoutInfo) {
        let area = layout.watch;
        if area.width == 0 || area.height == 0 { return; }
        let mut built = self.built_text();
        self.apply_filter_highlights(&mut built.lines);
        // Keep a copy of total lines for scrollbar/border handling.
        let total_lines = built.lines.len();
        let _ = total_lines;

        let rtext = RText::from(built.lines.iter().map(|l| to_rline(&l.spans)).collect::<Vec<_>>());
        let mut para = Paragraph::new(rtext);
        if self.wrap_on {
            para = para.wrap(Wrap { trim: false });
        }
        let visual_total = if self.wrap_on { para.line_count(area.width) } else { built.lines.len() };
        self.last_total_visual = visual_total;
        para = para.scroll((self.watch_scroll_y, if self.wrap_on { 0 } else { self.watch_scroll_x }));
        f.render_widget(para, area);
    }

    fn draw_history(&mut self, f: &mut Frame, layout: &LayoutInfo) {
        let area = layout.history;
        if area.width == 0 || area.height == 0 { return; }
        // Build rows.
        #[derive(Clone)]
        struct Row { spans: Vec<Span>, sel: Option<Selection>, selected_visual: bool, is_latest_row: bool }
        let mut rows: Vec<Row> = Vec::new();
        let latest_selected = matches!(self.selection, Selection::Latest);
        if latest_selected {
            rows.push(Row {
                spans: vec![Span::new(">>latest", SStyle { fg: Some(Col::Gray), bg: Some(Col::Blue), bold: true, ..Default::default() })],
                sel: Some(Selection::Latest), selected_visual: true, is_latest_row: true,
            });
        } else {
            rows.push(Row {
                spans: vec![Span::plain("  "), Span::new("latest", SStyle::fg(Col::Blue))],
                sel: Some(Selection::Latest), selected_visual: false, is_latest_row: true,
            });
        }
        let filtered = self.filtered_indices();
        for &ci in filtered.iter().rev() {
            let entry = self.history[ci].clone();
            let is_sel = matches!(self.selection, Selection::Entry(i) if i == ci);
            let ts_style = SStyle::fg(if entry.status { Col::Green } else { Col::Red });
            if is_sel {
                let marker_style = SStyle { bg: Some(Col::Indexed(8)), bold: true, ..Default::default() };
                let mut tstyle = ts_style;
                tstyle.bg = Some(Col::Indexed(8));
                tstyle.bold = true;
                rows.push(Row {
                    spans: vec![Span::new(">>", marker_style), Span::new(entry.timestamp.clone(), tstyle)],
                    sel: Some(Selection::Entry(ci)), selected_visual: true, is_latest_row: false,
                });
            } else {
                rows.push(Row {
                    spans: vec![Span::plain("  "), Span::new(entry.timestamp.clone(), ts_style)],
                    sel: Some(Selection::Entry(ci)), selected_visual: false, is_latest_row: false,
                });
            }
            if self.summary_on {
                let (ladd, ldel, cadd, cdel) = self.summary_for(ci);
                let mut spans = vec![
                    Span::plain("Line: "),
                    Span::new(format!("+ {:>6}", ladd), SStyle::fg(Col::Green)),
                    Span::plain(" "),
                    Span::new(format!("- {:>6}", ldel), SStyle::fg(Col::Red)),
                ];
                if is_sel {
                    for s in spans.iter_mut() {
                        s.style.bg = Some(Col::Indexed(8));
                        s.style.bold = true;
                    }
                }
                rows.push(Row { spans, sel: Some(Selection::Entry(ci)), selected_visual: is_sel, is_latest_row: false });
                if self.settings.enable_summary_char {
                    let mut spans = vec![
                        Span::plain("Char: "),
                        Span::new(format!("+ {:>6}", cadd), SStyle::fg(Col::Green)),
                        Span::plain(" "),
                        Span::new(format!("- {:>6}", cdel), SStyle::fg(Col::Red)),
                    ];
                    if is_sel {
                        for s in spans.iter_mut() {
                            s.style.bg = Some(Col::Indexed(8));
                            s.style.bold = true;
                        }
                    }
                    rows.push(Row { spans, sel: Some(Selection::Entry(ci)), selected_visual: is_sel, is_latest_row: false });
                }
            }
        }

        // Determine the row index of the current selection for scrolling.
        let sel_row = rows.iter().position(|r| {
            match (&r.sel, &self.selection) {
                (Some(Selection::Latest), Selection::Latest) => true,
                (Some(Selection::Entry(a)), Selection::Entry(b)) => a == b && r.spans.first().map(|s| s.text.starts_with(">>") || !s.text.starts_with("Line") && !s.text.starts_with("Char")).unwrap_or(false),
                _ => false,
            }
        }).unwrap_or(0);
        // Better: find the timestamp/latest row: it is the first row whose
        // sel matches and which is not a summary row. The rows are built in
        // order, so track explicitly:
        let mut sel_row_idx = 0usize;
        {
            let mut idx = 0usize;
            // latest row
            if matches!(self.selection, Selection::Latest) { sel_row_idx = 0; }
            else {
                idx = 1;
                for &ci in filtered.iter().rev() {
                    if matches!(self.selection, Selection::Entry(i) if i == ci) { sel_row_idx = idx; break; }
                    idx += 1;
                    if self.summary_on {
                        idx += 1;
                        if self.settings.enable_summary_char { idx += 1; }
                    }
                }
            }
        }
        let _ = sel_row;
        let height = area.height as usize;
        let mut offset = self.history_scroll_offset;
        if sel_row_idx < offset { offset = sel_row_idx; }
        if sel_row_idx >= offset + height { offset = sel_row_idx + 1 - height; }
        let max_off = rows.len().saturating_sub(height);
        if offset > max_off { offset = max_off; }
        self.history_scroll_offset = offset;
        self.history_row_map = rows.iter().map(|r| r.sel.clone()).collect();

        let buf = f.buffer_mut();
        for (vi, row) in rows.iter().skip(offset).take(height).enumerate() {
            let y = area.y + vi as u16;
            let rl = to_rline(&row.spans);
            buf.set_line(area.x, y, &rl, area.width);
            if row.selected_visual && !row.is_latest_row {
                // Extend the selection background across the text width.
                let w = row.spans.iter().map(|s| unicode_width::UnicodeWidthStr::width(s.text.as_str())).sum::<usize>();
                let rect = Rect::new(area.x, y, std::cmp::min(area.width, w as u16), 1);
                buf.set_style(rect, Style::default().bg(Color::Indexed(8)).add_modifier(Modifier::BOLD));
                // Re-apply text (set_style keeps symbols).
            }
        }
    }

    fn summary_for(&mut self, ci: usize) -> (usize, usize, usize, usize) {
        let entry = self.history[ci].clone();
        let key = format!("{}|{}|{}", ci, entry.timestamp, self.output_mode.label());
        if let Some(v) = self.summary_cache.get(&key) { return *v; }
        let prev = if ci > 0 { self.history[ci - 1].clone() } else { CommandResultData::default() };
        let eff = self.effective_settings();
        let v = textgen::summary_counts(&eff, &entry, &prev);
        self.summary_cache.insert(key, v);
        v
    }

    fn draw_border(&mut self, f: &mut Frame, layout: &LayoutInfo) {
        let area = f.area();
        let buf = f.buffer_mut();
        let style = Style::default().fg(Color::Indexed(8));
        if self.show_header {
            let y = layout.border_row_y;
            for x in 0..area.width {
                let ch = if x == layout.separator_x { "┬" } else { "─" };
                buf.set_string(x, y, ch, style);
            }
        }
        // Vertical bar/scrollbar in the body.
        let total = self.last_total_visual;
        let track = layout.body.height as usize;
        let scrollbar_active = self.settings.with_scrollbar && total > track && track > 0;
        let (thumb_start, thumb_len) = if scrollbar_active {
            let tl = std::cmp::max(1, (track * track) / total);
            let ts = (self.watch_scroll_y as usize * track) / total;
            (ts, tl)
        } else { (0, 0) };
        for row in 0..layout.body.height {
            let y = layout.body.y + row;
            let x = layout.separator_x;
            if x >= area.width { continue; }
            let ch = if scrollbar_active {
                let r = row as usize;
                if r >= thumb_start && r < thumb_start + thumb_len { "█" } else { "│" }
            } else { "│" };
            buf.set_string(x, y, ch, style);
        }
    }

    fn draw_help(&mut self, f: &mut Frame, area: Rect) {
        let vchunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Percentage(15), Constraint::Percentage(70), Constraint::Percentage(15)])
            .split(area);
        let hchunks = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(10), Constraint::Percentage(80), Constraint::Percentage(10)])
            .split(vchunks[1]);
        let popup = hchunks[1];
        self.last_help_inner_height = popup.height.saturating_sub(2);
        f.render_widget(Clear, popup);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Plain)
            .title(" [help] ")
            .style(Style::default().fg(Color::Indexed(7)));
        let pairs = self.help_lines();
        let mut lines: Vec<RLine> = Vec::new();
        for (key, desc) in &pairs {
            lines.push(RLine::from(vec![
                RSpan::styled(" - [", Style::default().fg(Color::Indexed(10))),
                RSpan::styled(key.clone(), Style::default().fg(Color::Indexed(3))),
                RSpan::styled("] key :", Style::default().fg(Color::Indexed(10))),
            ]));
            lines.push(RLine::from(vec![
                RSpan::styled("         ", Style::default().fg(Color::Indexed(10))),
                RSpan::styled(desc.clone(), Style::default().fg(Color::Indexed(15))),
            ]));
        }
        let para = Paragraph::new(RText::from(lines)).block(block).scroll((self.help_scroll, 0));
        f.render_widget(para, popup);
    }

    fn draw_exit(&mut self, f: &mut Frame, area: Rect) {
        let w = std::cmp::min(32, area.width);
        let h = 5u16;
        let x = area.x + area.width.saturating_sub(w) / 2;
        let y = area.y + area.height.saturating_sub(h) / 2;
        let popup = Rect::new(x, y, w, h);
        f.render_widget(Clear, popup);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Double)
            .title(" [exit] ")
            .style(Style::default().fg(Color::Indexed(6)).add_modifier(Modifier::BOLD));
        let lines = vec![
            RLine::from(" Exit hwatch?"),
            RLine::from("   Press 'Y' or 'Q'  : Quit."),
            RLine::from("   Press 'N' or 'Esc': Stay."),
        ];
        let para = Paragraph::new(RText::from(lines)).block(block);
        f.render_widget(para, popup);
    }
}

fn wrapped_count(text: &str, width: usize) -> usize {
    if width == 0 { return 1; }
    // Approximation of the word wrapper used for scrolling bookkeeping:
    // greedy word-aware wrapping. Simple content (the common case in
    // scroll tests) wraps exactly at the pane width.
    let mut lines = 1usize;
    let mut cur = 0usize;
    for word in text.split_inclusive(' ') {
        let ww = unicode_width::UnicodeWidthStr::width(word);
        if cur > 0 && cur + ww > width {
            lines += 1;
            cur = 0;
        }
        // A single over-long word wraps by characters.
        let mut rest = ww;
        while cur + rest > width {
            let avail = width - cur;
            rest -= avail;
            lines += 1;
            cur = 0;
        }
        cur += rest;
    }
    lines
}

pub struct LayoutInfo {
    pub header: Rect,
    pub border_row_y: u16,
    pub body: Rect,
    pub watch: Rect,
    pub history: Rect,
    pub separator_x: u16,
}

impl LayoutInfo {
    pub fn in_watch(&self, x: u16, y: u16) -> bool {
        x >= self.watch.x && x < self.watch.x + self.watch.width && y >= self.watch.y && y < self.watch.y + self.watch.height
    }
    pub fn in_history(&self, x: u16, y: u16) -> bool {
        self.history.width > 0 && x >= self.history.x && x < self.history.x + self.history.width && y >= self.history.y && y < self.history.y + self.history.height
    }
    pub fn history_click(&self, row: u16, map: &[Option<Selection>], offset: usize) -> Option<Selection> {
        if row < self.history.y { return None; }
        let idx = offset + (row - self.history.y) as usize;
        map.get(idx).cloned().flatten()
    }
}

pub fn compute_layout(area: Rect, show_header: bool, show_history: bool, border_on: bool) -> LayoutInfo {
    let header_h = if show_header { 2 } else { 0 };
    let border_h = if show_header && border_on { 1 } else { 0 };
    let body_y = header_h + border_h;
    let body_h = area.height.saturating_sub(body_y);
    let sep = if border_on { 1 } else { 0 };
    let (watch_w, history_w) = if show_history {
        let hw = std::cmp::min(25, area.width);
        (area.width.saturating_sub(hw + sep), hw)
    } else if show_header {
        (area.width.saturating_sub(sep), 0)
    } else {
        // Collapsed history strip.
        (area.width.saturating_sub(2 + sep), 2)
    };
    let watch = Rect::new(area.x, area.y + body_y, watch_w, body_h);
    let separator_x = area.x + watch_w;
    let history = Rect::new(separator_x + sep, area.y + body_y, history_w, body_h);
    LayoutInfo {
        header: Rect::new(area.x, area.y, area.width, header_h),
        border_row_y: area.y + header_h,
        body: Rect::new(area.x, area.y + body_y, area.width, body_h),
        watch,
        history,
        separator_x,
    }
}

pub fn keydef_from_event(key: &KeyEvent) -> KeyDef {
    let (ctrl, alt, shift_m) = (
        key.modifiers.contains(KeyModifiers::CONTROL),
        key.modifiers.contains(KeyModifiers::ALT),
        key.modifiers.contains(KeyModifiers::SHIFT),
    );
    let mut kd = KeyDef { code: KeyCodeDef::Esc, ctrl, alt, shift: shift_m };
    kd.code = match key.code {
        KeyCode::Char(c) => {
            if c.is_ascii_alphabetic() {
                if c.is_ascii_uppercase() { kd.shift = true; }
                KeyCodeDef::Char(c.to_ascii_lowercase())
            } else {
                KeyCodeDef::Char(c)
            }
        }
        KeyCode::F(n) => KeyCodeDef::F(n),
        KeyCode::Up => KeyCodeDef::Up,
        KeyCode::Down => KeyCodeDef::Down,
        KeyCode::Left => KeyCodeDef::Left,
        KeyCode::Right => KeyCodeDef::Right,
        KeyCode::Home => KeyCodeDef::Home,
        KeyCode::End => KeyCodeDef::End,
        KeyCode::PageUp => KeyCodeDef::PageUp,
        KeyCode::PageDown => KeyCodeDef::PageDown,
        KeyCode::Backspace => KeyCodeDef::Backspace,
        KeyCode::Enter => KeyCodeDef::Enter,
        KeyCode::Tab => KeyCodeDef::Tab,
        KeyCode::BackTab => { kd.shift = true; KeyCodeDef::BackTab }
        KeyCode::Esc => KeyCodeDef::Esc,
        KeyCode::Delete => KeyCodeDef::Delete,
        KeyCode::Insert => KeyCodeDef::Insert,
        _ => KeyCodeDef::Esc,
    };
    kd
}

// ----- TUI entry point -----

pub fn run_tui(
    settings: Settings,
    keymap: KeyMap,
    loaded: Vec<CommandResultData>,
    logfile: Option<String>,
) -> i32 {
    // Terminal setup, mirroring the reference failure behaviour: if the
    // terminal cannot be put into raw mode, exit silently with success.
    if enable_raw_mode().is_err() {
        return 0;
    }
    let mut stdout = io::stdout();
    if execute!(stdout, EnterAlternateScreen).is_err() {
        let _ = disable_raw_mode();
        return 0;
    }
    if settings.mouse {
        let _ = execute!(stdout, crossterm::event::EnableMouseCapture);
    } else {
        let _ = execute!(stdout, crossterm::event::DisableMouseCapture);
    }
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            return 0;
        }
    };
    let _ = terminal.hide_cursor();

    let control = exec::new_control(settings.interval);
    let command = settings.command_string();
    let rx = exec::spawn_executor(settings.clone(), command, control.clone());
    let mut app = App::new(settings.clone(), keymap, control.clone(), loaded);
    let mut current_layout = compute_layout(Rect::new(0, 0, 80, 24), app.show_header, app.show_history, app.border_on);

    let code = run_loop(&mut terminal, &mut app, &rx, logfile, &mut current_layout);

    control.lock().unwrap().stopped = true;
    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();
    code
}

fn run_loop(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
    rx: &std::sync::mpsc::Receiver<CommandResultData>,
    logfile: Option<String>,
    current_layout: &mut LayoutInfo,
) -> i32 {
    loop {
        // Drain executor results.
        loop {
            match rx.try_recv() {
                Ok(r) => {
                    let effects = app.on_result(r);
                    for e in effects {
                        match e {
                            AppSideEffect::Log(res) => {
                                if let Some(path) = &logfile {
                                    crate::append_log(path, &res);
                                }
                            }
                            AppSideEffect::After(before, after) => {
                                if let Some(cmd) = &app.settings.after_command {
                                    crate::spawn_aftercommand(cmd, &before, &after);
                                }
                            }
                            AppSideEffect::Beep => {
                                let _ = execute!(io::stdout(), crossterm::style::Print("\x07"));
                            }
                        }
                    }
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => break,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => break,
            }
        }

        let mut layout_snapshot: Option<LayoutInfo> = None;
        let _ = terminal.draw(|f| {
            app.draw(f);
            layout_snapshot = Some(compute_layout(f.area(), app.show_header, app.show_history, app.border_on));
        });
        if let Some(l) = layout_snapshot { *current_layout = l; }

        if app.should_quit { return 0; }

        if app.mouse_capture_changed {
            app.mouse_capture_changed = false;
            if app.mouse_on {
                let _ = execute!(io::stdout(), crossterm::event::EnableMouseCapture);
            } else {
                let _ = execute!(io::stdout(), crossterm::event::DisableMouseCapture);
            }
        }

        // Poll for input briefly so new results are shown promptly.
        match event::poll(Duration::from_millis(50)) {
            Ok(true) => {
                match event::read() {
                    Ok(Event::Key(key)) => app.handle_key(key),
                    Ok(Event::Mouse(m)) => {
                        if app.mouse_on {
                            app.handle_mouse(m, current_layout);
                        }
                    }
                    Ok(Event::Resize(_, _)) => {}
                    _ => {}
                }
            }
            _ => {}
        }
        if app.should_quit { return 0; }
    }
}

pub fn action_name(a: Action) -> Option<&'static str> {
    ACTION_INFO.iter().find(|(x, _, _)| *x == a).map(|(_, n, _)| *n)
}

pub fn _unused(_: Option<Action>) { let _ = action_from_name("up"); }
