fn first_occurrence<T: Clone + Send + Sync + 'static>(m: &clap::ArgMatches, name: &str) -> Option<T> {
    if let Some(mut occ) = m.get_occurrences::<T>(name) {
        if let Some(first) = occ.next() {
            let vals: Vec<T> = first.cloned().collect();
            if let Some(v) = vals.into_iter().next() { return Some(v); }
        }
    }
    None
}

fn all_occurrence_values<T: Clone + Send + Sync + 'static>(m: &clap::ArgMatches, name: &str) -> Vec<T> {
    let mut out = Vec::new();
    if let Some(occ) = m.get_occurrences::<T>(name) {
        for one in occ {
            for v in one { out.push(v.clone()); }
        }
    }
    out
}

fn has_arg(m: &clap::ArgMatches, name: &str) -> bool {
    m.get_occurrences::<String>(name).is_some() || m.index_of(name).is_some()
}

fn clap_custom_error(msg: &str) -> ! {
    eprintln!("error: {}\n\nUsage: hwatch [OPTIONS] [command]...\n\nFor more information, try '--help'.", msg);
    std::process::exit(2);
}

fn confirm_log_reuse() {
    loop {
        print!("Log to the same file? (Y/n) ");
        let _ = io::stdout().flush();
        let mut s = String::new();
        let _ = io::stdin().read_line(&mut s);
        match s.trim().to_ascii_lowercase().as_str() {
            "" | "y" | "yes" => break,
            "n" | "no" => std::process::exit(1),
            _ => continue,
        }
    }
}

pub fn append_log(path: &str, result: &CommandResultData) {
    use std::fs::OpenOptions;
    if let Ok(mut f) = OpenOptions::new().create(true).append(true).open(path) {
        if let Ok(s) = serde_json::to_string(result) {
            let _ = writeln!(f, "{}", s);
        }
    }
}

pub fn spawn_aftercommand(cmd: &str, before: &CommandResultData, after: &CommandResultData) {
    let data = serde_json::to_string(&AfterCommandData {
        before_result: before.clone(),
        after_result: after.clone(),
    }).unwrap_or_default();
    let _ = Command::new("sh").arg("-c").arg(cmd).env("HWATCH_DATA", data).spawn();
}

fn load_logfile(path: &str) -> Vec<CommandResultData> {
    // The parent directory is required; an empty path has no parent.
    let parent = Path::new(path).parent().unwrap();
    if !parent.as_os_str().is_empty() && !parent.exists() {
        clap_custom_error(&format!("error: directory \"{}\" is not exists.", parent.display()));
    }

    if Path::new(path).is_dir() {
        // Reading JSON from a directory fails inside serde with an io error.
        let f = std::fs::File::open(path).unwrap();
        let err = serde_json::from_reader::<_, serde_json::Value>(f).err();
        if let Some(e) = err {
            eprintln!("file \"{}\" is exists and json parse error.\n{:?}", path, e);
        }
        confirm_log_reuse();
        return Vec::new();
    }

    match std::fs::read(path) {
        Ok(bytes) => {
            if bytes.is_empty() {
                eprintln!("file \"{}\" is exists and empty.", path);
                confirm_log_reuse();
                return Vec::new();
            }
            let mut history = Vec::new();
            let text = String::from_utf8_lossy(&bytes);
            for raw_line in text.split('\n') {
                let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
                if line.trim().is_empty() { continue; }
                match serde_json::from_str::<CommandResultData>(line) {
                    Ok(v) => history.push(v),
                    Err(e) => {
                        eprintln!("file \"{}\" is exists and json parse error.\n{:?}", path, e);
                        confirm_log_reuse();
                        return Vec::new();
                    }
                }
            }
            history
        }
        Err(e) if e.kind() == io::ErrorKind::NotFound => Vec::new(),
        Err(e) => {
            eprintln!("file \"{}\" is exists and load error.\n{:?}", path, e);
            confirm_log_reuse();
            Vec::new()
        }
    }
}

fn run_batch(settings: Settings, logfile: Option<String>) -> i32 {
    let control = exec::new_control(settings.interval);
    let command = settings.command_string();
    let rx = exec::spawn_executor(settings.clone(), command, control);
    let mut before = CommandResultData::default();
    loop {
        match rx.recv() {
            Ok(result) => {
                let built = textgen::build_text_for(&settings, &result, &before, true);
                println!("\x1b[38;5;240m=====[{}]=========================\x1b[0m", result.timestamp);
                for line in &built.lines {
                    println!("{}", textgen::line_to_ansi(line));
                }
                let _ = io::stdout().flush();
                if let Some(path) = &logfile {
                    append_log(path, &before);
                }
                if settings.beep {
                    println!("\x07");
                    let _ = io::stdout().flush();
                }
                if let Some(cmd) = &settings.after_command {
                    spawn_aftercommand(cmd, &before, &result);
                }
                before = result;
            }
            Err(_) => {
                // The worker thread has gone away (for example it hit an
                // invalid interval); the reference process stays alive.
                loop { std::thread::park(); }
            }
        }
    }
}

fn main() -> ExitCode {
    // HWATCH environment variable: its whitespace-separated tokens are
    // inserted before the actual command-line arguments.
    let mut argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    if argv.len() > 1 {
        if let Ok(hw) = std::env::var("HWATCH") {
            let extra: Vec<std::ffi::OsString> = hw.split_whitespace().map(|s| s.into()).collect();
            if !extra.is_empty() {
                let mut new_argv = Vec::with_capacity(argv.len() + extra.len());
                new_argv.push(argv[0].clone());
                new_argv.extend(extra);
                new_argv.extend(argv[1..].iter().cloned());
                argv = new_argv;
            }
        }
    }

    let m = build_cli().get_matches_from(argv);

    let command: Vec<String> = m.get_many::<String>("command")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    // Logfile handling happens before most other validation.
    #[derive(Debug, PartialEq)]
    enum LogArg { None, NoValue, Path(String) }
    let log_arg = {
        let vals = all_occurrence_values::<String>(&m, "logfile");
        if m.get_occurrences::<String>("logfile").is_none() && !has_arg(&m, "logfile") {
            LogArg::None
        } else if vals.is_empty() {
            LogArg::NoValue
        } else {
            LogArg::Path(vals[0].clone())
        }
    };

    let mut loaded_history: Vec<CommandResultData> = Vec::new();
    let mut logfile_path: Option<String> = None;
    if let LogArg::Path(p) = &log_arg {
        loaded_history = load_logfile(p);
        logfile_path = Some(p.clone());
    }

    let mut command = command;
    if command.is_empty() {
        if let Some(last) = loaded_history.last() {
            if !last.command.is_empty() {
                command = vec![last.command.clone()];
            }
        }
    }

    // Output mode (present without a value is an error in the reference).
    let output_mode = {
        if m.get_occurrences::<String>("output").is_none() {
            OutputMode::Output
        } else {
            let vals = all_occurrence_values::<String>(&m, "output");
            let first = vals.into_iter().next().unwrap();
            OutputMode::parse(&first).unwrap()
        }
    };

    let keymap_strings: Vec<String> = all_occurrence_values::<String>(&m, "keymap");
    let keymap = match keymap::KeyMap::new(&keymap_strings) {
        Ok(k) => k,
        Err(_) => {
            eprint!("Failed to parse keymap.\n");
            return ExitCode::from(1);
        }
    };

    if command.is_empty() {
        clap_custom_error("error: command not specified and logfile is empty.");
    }

    let differences = {
        if m.get_occurrences::<String>("differences").is_none() {
            DiffMode::None
        } else {
            let vals = all_occurrence_values::<String>(&m, "differences");
            match vals.into_iter().next().as_deref() {
                Some("watch") => DiffMode::Watch,
                Some("line") => DiffMode::Line,
                Some("word") => DiffMode::Word,
                _ => DiffMode::None,
            }
        }
    };

    let settings = Settings {
        batch: m.get_flag("batch"),
        beep: m.get_flag("beep"),
        border: m.get_flag("border"),
        with_scrollbar: m.get_flag("with-scrollbar"),
        mouse: m.get_flag("mouse"),
        color: m.get_flag("color"),
        reverse: m.get_flag("reverse"),
        compress: m.get_flag("compress"),
        no_title: m.get_flag("no-title"),
        enable_summary_char: m.get_flag("enable-summary-char"),
        line_number: m.get_flag("line-number"),
        no_help_banner: m.get_flag("no-help-banner"),
        no_summary: m.get_flag("no-summary"),
        exec: m.get_flag("exec"),
        diff_output_only: m.get_flag("diff-output-only"),
        after_command: first_occurrence::<String>(&m, "aftercommand"),
        logfile: logfile_path.clone(),
        shell_command: first_occurrence::<String>(&m, "shell").unwrap_or_else(|| "sh -c".to_string()),
        interval: first_occurrence::<f64>(&m, "interval").unwrap_or(2.0),
        precise: m.get_flag("precise"),
        limit: first_occurrence::<u32>(&m, "limit").unwrap_or(5000),
        tab_size: first_occurrence::<u16>(&m, "tab-size").unwrap_or(4),
        differences,
        output: output_mode,
        keymap_strings,
        command,
    };

    if settings.batch {
        return ExitCode::from(run_batch(settings, logfile_path) as u8);
    }

    ExitCode::from(app::run_tui(settings, keymap, loaded_history, logfile_path) as u8)
}

