                if st.italic { codes.push("3".to_string()); }
                if st.underline { codes.push("4".to_string()); }
                if st.reverse { codes.push("7".to_string()); }
                if let Some(c) = st.fg { codes.push(col_fg(c)); }
                if let Some(c) = st.bg { codes.push(col_bg(c)); }
                out.push_str(&format!("\\x1b[{}m{}", codes.join(";"), span.text));
                styled_active = true;
            }
        }
        if styled_active { out.push_str("\\x1b[0m"); }
