// ---------- word wrapping (used when wrap mode is on) ----------

pub fn wrap_spans(spans: &[Span], width: usize) -> Vec<Vec<Span>> {
    if width == 0 { return vec![spans.to_vec()]; }
    // Flatten to chars.
    let mut chars: Vec<(char, SStyle)> = Vec::new();
    for sp in spans {
        for c in sp.text.chars() { chars.push((c, sp.style)); }
    }
    if chars.is_empty() { return vec![vec![Span::plain("")]]; }

    // Tokenize: words (non-space runs) and individual whitespace chars.
    enum Tok { Word(Vec<(char, SStyle)>), Space((char, SStyle)) }
    let mut toks: Vec<Tok> = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i].0 == ' ' || chars[i].0 == '\t' {
            toks.push(Tok::Space(chars[i]));
            i += 1;
        } else {
            let mut w = Vec::new();
            while i < chars.len() && chars[i].0 != ' ' && chars[i].0 != '\t' {
                w.push(chars[i]);
                i += 1;
            }
            toks.push(Tok::Word(w));
        }
    }

    fn width_of(v: &[(char, SStyle)]) -> usize {
        v.iter().map(|(c, _)| unicode_width::UnicodeWidthChar::width(*c).unwrap_or(0)).sum()
    }
    fn spans_of(v: &[(char, SStyle)]) -> Vec<Span> {
        let mut out: Vec<Span> = Vec::new();
        for (c, st) in v {
            if let Some(last) = out.last_mut() {
                let last_span: &mut Span = last;
                if last_span.style == *st { last_span.text.push(*c); continue; }
            }
            out.push(Span::new(c.to_string(), *st));
        }
        if out.is_empty() { out.push(Span::plain("")); }
        out
    }

    let mut lines: Vec<Vec<Span>> = Vec::new();
    let mut line: Vec<(char, SStyle)> = Vec::new();
    let mut pending: Vec<(char, SStyle)> = Vec::new();
    let mut line_has_word = false;

    for tok in toks {
        match tok {
            Tok::Space(sp) => pending.push(sp),
            Tok::Word(word) => {
                let ww = width_of(&word);
                let pw = width_of(&pending);
                let lw = width_of(&line);
                if line_has_word && lw + pw + ww > width {
                    // Wrap before this word. One whitespace character is
                    // consumed at the end of the full line; any remaining
                    // ones lead the next line.
                    lines.push(spans_of(&line));
                    line = Vec::new();
                    if pending.len() > 1 {
                        line.extend_from_slice(&pending[1..]);
                    }
                    pending = Vec::new();
                    line_has_word = false;
                } else {
                    line.extend_from_slice(&pending);
                    pending = Vec::new();
                }
                // Add the word, splitting it if it alone is too long.
                let mut idx = 0;
                while idx < word.len() {
                    let avail = width.saturating_sub(width_of(&line));
                    if avail == 0 {
                        lines.push(spans_of(&line));
                        line = Vec::new();
                        line_has_word = false;
                        continue;
                    }
                    let mut take = 0usize;
                    let mut tw = 0usize;
                    while idx + take < word.len() {
                        let cw = unicode_width::UnicodeWidthChar::width(word[idx + take].0).unwrap_or(0);
                        if tw + cw > avail { break; }
                        tw += cw;
                        take += 1;
                    }
                    if take == 0 {
                        // A wide char that cannot fit: emit the line and retry.
                        if !line.is_empty() {
                            lines.push(spans_of(&line));
                            line = Vec::new();
                            line_has_word = false;
                            continue;
                        } else {
                            take = 1;
                        }
                    }
                    line.extend_from_slice(&word[idx..idx + take]);
                    idx += take;
                    if idx < word.len() {
                        lines.push(spans_of(&line));
                        line = Vec::new();
                        line_has_word = false;
                    }
                }
                if !word.is_empty() { line_has_word = true; }
            }
        }
    }
    line.extend_from_slice(&pending);
    lines.push(spans_of(&line));
    lines
}

pub fn wrapped_line_count(text: &str, width: usize) -> usize {
    if width == 0 { return 1; }
    wrap_spans(&[Span::plain(text.to_string())], width).len()
}
