import subprocess, os, re, json, time, signal
def fix(b):
    return re.sub(rb'202\d-\d\d-\d\d \d\d:\d\d:\d\d\.\d\d\d', b'<TS>', b or b'')
def run(exe,args,dur=1.4,stdin=None):
    try:
        p=subprocess.run([exe]+args,capture_output=True,timeout=dur,cwd="/tmp/hwtest",input=stdin)
        return (p.returncode,fix(p.stdout),fix(p.stderr))
    except subprocess.TimeoutExpired as e:
        return ("TO",fix(e.stdout),fix(e.stderr))

def compare_batch_log(name,args,content=None,dur=1.4,stdin=None):
    path=f"/tmp/hwtest/cmp_{name}.json"
    def setup():
        try: os.remove(path)
        except: pass
        if content is not None: open(path,"wb").write(content)
    setup(); a=run("/workspace/executable",[x.replace("{LOG}",path) for x in args],dur,stdin)
    af=open(path,"rb").read() if os.path.exists(path) else b"<none>"
    setup(); b=run("/tmp/oursbin/executable",[x.replace("{LOG}",path) for x in args],dur,stdin)
    bf=open(path,"rb").read() if os.path.exists(path) else b"<none>"
    ok=(a==b and fix(af)==fix(bf))
    print(name,"SAME" if ok else "DIFF")
    if not ok:
        print(" orig run",a,"file",fix(af)); print(" ours run",b,"file",fix(bf))

