s += r'''

// ---------- difflib-style SequenceMatcher diff ----------

fn seq_diff(a: &[String], b: &[String]) -> Vec<Op> {
    use std::collections::HashMap;
    // Map each token in b to its (ascending) positions.
    let mut b2j: HashMap<&str, Vec<usize>> = HashMap::new();
    for (i, t) in b.iter().enumerate() {
        b2j.entry(t.as_str()).or_default().push(i);
    }

    fn longest_match(
        a: &[String],
        b2j: &std::collections::HashMap<&str, Vec<usize>>,
        a_low: usize,
        a_high: usize,
        b_low: usize,
        b_high: usize,
    ) -> (usize, usize, usize) {
        use std::collections::HashMap;
        let mut best = (a_low, b_low, 0usize);
        let mut j2len: HashMap<usize, usize> = HashMap::new();
        for i in a_low..a_high {
            let mut newj2len: HashMap<usize, usize> = HashMap::new();
            if let Some(js) = b2j.get(a[i].as_str()) {
                for &j in js {
                    if j < b_low { continue; }
                    if j >= b_high { break; }
                    let k = if j > 0 { j2len.get(&(j - 1)).copied().unwrap_or(0) + 1 } else { 1 };
                    newj2len.insert(j, k);
                    if k > best.2 {
                        best = (i + 1 - k, j + 1 - k, k);
                    }
                }
            }
            j2len = newj2len;
        }
        best
    }

    fn matching_blocks(
        a: &[String],
        b2j: &std::collections::HashMap<&str, Vec<usize>>,
        a_low: usize,
        a_high: usize,
        b_low: usize,
        b_high: usize,
        out: &mut Vec<(usize, usize, usize)>,
    ) {
        let (i, j, k) = longest_match(a, b2j, a_low, a_high, b_low, b_high);
        if k == 0 { return; }
        if a_low < i && b_low < j {
            matching_blocks(a, b2j, a_low, i, b_low, j, out);
        }
        out.push((i, j, k));
        if i + k < a_high && j + k < b_high {
            matching_blocks(a, b2j, i + k, a_high, j + k, b_high, out);
        }
    }

    let mut blocks: Vec<(usize, usize, usize)> = Vec::new();
    if !a.is_empty() && !b.is_empty() {
        matching_blocks(a, &b2j, 0, a.len(), 0, b.len(), &mut blocks);
    }
    blocks.sort();
    // Collapse adjacent blocks and add the sentinel.
    let mut collapsed: Vec<(usize, usize, usize)> = Vec::new();
    for (i, j, k) in blocks {
        if let Some(last) = collapsed.last_mut() {
            let (li, lj, lk): &mut (usize, usize, usize) = last;
            if *li + *lk == i && *lj + *lk == j {
                *lk += k;
                continue;
            }
        }
        collapsed.push((i, j, k));
    }
    collapsed.push((a.len(), b.len(), 0));

    let mut ops = Vec::new();
    let (mut ai, mut bi) = (0usize, 0usize);
    for (i, j, k) in collapsed {
        if ai < i && bi < j {
            for t in &a[ai..i] { ops.push(Op::Del(t.clone())); }
            for t in &b[bi..j] { ops.push(Op::Ins(t.clone())); }
        } else if ai < i {
            for t in &a[ai..i] { ops.push(Op::Del(t.clone())); }
        } else if bi < j {
            for t in &b[bi..j] { ops.push(Op::Ins(t.clone())); }
        }
        for t in &a[i..i + k] { ops.push(Op::Eq(t.clone())); }
        ai = i + k;
        bi = j + k;
    }
    ops
}
'''
