import pathlib
p=pathlib.Path("src/app.rs"); s=p.read_text()
start=s.find("    fn apply_filter_highlights(&self, lines: &mut Vec<DisplayLine>) {")
end=s.find("    // ----- key handling -----", start)
assert start!=-1 and end!=-1
new_fn = '''    fn apply_filter_highlights(&self, lines: &mut Vec<DisplayLine>) {
        if self.filter.is_none() { return; }
        let ms = self.matches(lines);
        if ms.is_empty() { return; }
        let focused = if self.focused_match < ms.len() { self.focused_match } else { 0 };
        for (li, line) in lines.iter_mut().enumerate() {
            // Matches on this line: (start, end, global index).
            let line_matches: Vec<(usize, usize, usize)> = ms.iter().enumerate()
                .filter(|(_, (l, _, _))| *l == li)
                .map(|(mi, (_, s, e))| (*s, *e, mi))
                .collect();
            if line_matches.is_empty() { continue; }
            let mut new_spans: Vec<Span> = Vec::new();
            let mut pos = 0usize;
            for span in &line.spans {
                let span_chars: Vec<char> = span.text.chars().collect();
                let span_len = span_chars.len();
                if span_len == 0 { continue; }
                // Cut points inside this span.
                let mut cuts: Vec<usize> = vec![pos, pos + span_len];
                for (ms_, me, _) in &line_matches {
                    if *ms_ > pos && *ms_ < pos + span_len { cuts.push(*ms_); }
                    if *me > pos && *me < pos + span_len { cuts.push(*me); }
                }
                cuts.sort_unstable();
                cuts.dedup();
                for w in cuts.windows(2) {
                    let (cs, ce) = (w[0], w[1]);
                    if cs >= ce { continue; }
                    let text: String = span_chars[cs - pos..ce - pos].iter().collect();
                    let overlap = line_matches.iter().find(|(ms_, me, _)| cs < *me && ce > *ms_);
                    let style = if let Some((ms_, _, mi)) = overlap {
                        SStyle {
                            fg: Some(Col::Black),
                            bg: Some(if cs == *ms_ && *mi == focused { Col::Yellow } else { Col::Cyan }),
                            ..Default::default()
                        }
                    } else { span.style };
                    if let Some(last) = new_spans.last_mut() {
                        let last_span: &mut Span = last;
                        if last_span.style == style { last_span.text.push_str(&text); continue; }
                    }
                    new_spans.push(Span::new(text, style));
                }
                pos += span_len;
            }
            if new_spans.is_empty() { new_spans.push(Span::plain("")); }
            line.spans = new_spans;
        }
    }

'''
s = s[:start] + new_fn + s[end:]
p.write_text(s)
